const ARTS=[{"n":0,"p":1,"c":"قرار المصادقة","t":"قرار رقم (10) لسنة 2025 الخاص بالتصديق على (مدونة الأحكام الشرعية في مسائل الأحوال الشخصية وفق المذهب الشيعي الجعفري) وتعد ملحقاً للقانون رقم (1) لسنة 2025 قانون تعديل قانون الأحوال الشخصية رقم (188) لسنة 1959. بناءً على ما أقرّه مجلس النواب استناداً إلى أحكام البند (أولاً) من المادة (61) والبند (ثالثاً) من المادة (73) من الدستور والمادة (1) من القانون رقم (1) لسنة 2025، قررنا ما هو آتٍ: أولاً: المصادقة على (مدونة الأحكام الشرعية في مسائل الأحوال الشخصية وفق المذهب الشيعي الجعفري) وتعد ملحقاً للقانون رقم (1) لسنة 2025. ثانياً: ينفذ هذا القرار والمدونة من تاريخ نشرهما في الجريدة الرسمية. كُتب ببغداد في الثامن من شهر ربيع الثاني لسنة 1447 هجرية الموافق للثلاثين من شهر أيلول لسنة 2025 ميلادية. عبد اللطيف جمال رشيد، رئيس الجمهورية. (الوقائع العراقية - العدد 4843 في 6 تشرين الأول 2025)"},{"n":1,"p":3,"c":"الباب الأول - الزواج","t":"ال زواج: ه وعقد بين الرجل والم رأة تتحق قبه علاقة خاصة بينهماي ّح لبس ببها كل منهما على الآخر."},{"n":2,"p":3,"c":"الباب الأول - الزواج › الفصل الأول - عقد الزواج","t":"يشترط في عقد الزواج: أولاً: الإيجاب والقبول اللفظيّ ان، ف لا تكفي الكتابة ولا الإش ارة المفهمة من غير الأخ رس ومن بحكمه. ثانياً: الموالاة بين الإيجاب والقبول، بمعنى أن لا يقع بينهما فصل طويل عرفاً. ثالثاً: تط ابق الإيج اب والقبول في متعلق ات العقد من المهر والش روط ونحوه ا، فإذا اختلفا لم يصح. رابعاً: أن يكون العاقد المج ري للص يغة قاص داً لإنش اء معناها حقيقة، ف لا عب رة بعقد الهازل والساهي ونحوهما ممن لا قصد له معتد به. خامساً: أن يكون العاقد عاقلاً بالغاً. سادساً: التنجي ز، فل وعلّقه على أمر مس تقبل معل وم الحصول أو متوقّ ع الحصول أو أمر حالي محتمل الحصول لم يصحّ. سابعاً: رض ا الزوجين واقع اً، فل وأك ره أحدهما أو كلاهما على الزواج لم يص حّ، ويقصد بالإكراه ما نصت عليه المادة (، )١١٣ولو تظاهر بالكراهة مع حص ول الرضا القلبي صحّ. ثامن اً: تعي ين الزوجين على وجه يمت از كل منهما عن الآخ رين بالاسم أو الوص ف أو الإشارة."},{"n":3,"p":4,"c":"الباب الأول - الزواج › الفصل الأول - عقد الزواج","t":"يص ّح التوكيل في الزواج من أحد الطرفين أو كليهما. أي جهة كان"},{"n":4,"p":4,"c":"الباب الأول - الزواج › الفصل الأول - عقد الزواج","t":"لا يص ّح العقد الصادر من الوكيل على خلاف ما عيّنه الموكّل من ّ الا مع إجازة المو ّك للاحق اً.وهك ذا كل عقد ص ادر من غير الوكي لومن بحكمه المسمى بالفضولي فإنه يص ّح بالإجازة."},{"n":5,"p":4,"c":"الباب الأول - الزواج › الفصل الأول - عقد الزواج","t":"يكفي في صورة العقد بعد تعي ين المهر أن تق ول الزوجة لل زوج(: زوجت كنفسي على المهر المعلوم)، فيقول الزوج(: قبلت التزويج). وإذا كانت الزوجة قد وكلت وكيلاً قال وكيلها لل زوج(: زوجت كم وكلتي فلانة على المهر المعلوم)، فيقول الزوج(: قبلت التزويج). وإذا كان الزوج قد وك لوك يلاً قالت الزوجة لوكي لال زوج(: زوج ت موكل كفلان اً نفسي على المهر المعلوم)، فيقول الوكيل(: قبلت التزويج لموكلي فلان). وإذا كان كل من الزوج والزوجة قد وك لوك يلا قال وكيل الزوجة لوكي لال زوج: (زوجت موكلك فلاناً موكلتي فلانة على المهر المعلوم)، فيقول وكيل الزوج(: قبلت التزويج لموكلي فلان)."},{"n":6,"p":4,"c":"الباب الأول - الزواج › الفصل الأول - عقد الزواج","t":"يجوز أن يُشترط في عقد الزواج كّل فعل أو ترك مش روع، ويج بعلى المش روط عليه الوفاء به، لكن تخلّفه أو تعذّره لا يوجب الخيار -أي حق الفسخ -للمشروط له، ولكن يجوز له اللجوء الى القضاء لإجبار المتخلّف على الوفاء به."},{"n":7,"p":4,"c":"الباب الأول - الزواج › الفصل الأول - عقد الزواج","t":"لا يص ّح اشتراط الخيار في عقد الزواج مطلق اً -ولك ن إذا اش ترط فيه وجود ص فة كمال -كالبكارة في المرأة -أو الخلو من عيب -كالإصابة بمرض مزمن -ثم ظهر التخلف عنه يجوز للطرف الآخر فسخ العقد."},{"n":8,"p":4,"c":"الباب الأول - الزواج › الفصل الأول - عقد الزواج","t":"اولاً: يجوز أن تشترط المرأة أن تكون هي -م ثلاً -وكيل ة عن الزوج في طلاق نفسها مطلقاً أو في حالات معينة كتعسر الحياة الزوجية بينهما نهائياً بتشخيص قاضي محكمة الأح وال الشخصية مثلاً، أو وجود بعض العيوب في الزوج غير ما يثبت به لها حق الفسخ وفقاً لما نصت عليه المادة (٥٨)من هذه المدونة، أو عند فقد الزوج وعدم العثور على أثر منه بالرغم من الفحص عنه ستة أشهر مثلاً، أو مع إدمانه للم واد المخ درة وعدم إقلاعه عنه ا. وإذا كانت الوكالة في ضمن عقد الزواج أو في عقد لازم آخر لم يكن للزوج عزلها عن الوكالة مطلقاً. ثانياً: إذا اشترطت المرأة الوكالة عن الزوج في الطلاق ولمي تم التصريح فيها بكونه أعم من الطلاق خلعاً -أي الطلاق بف داء -ل م يكن لها الا إيق اع الطلاق غير الخلعي، ويق ع هذا الطلاق رجعياً أو بائناً حسب اخ تلاف الح الات، وإذا وقع رجعياً ورجع الزوج في أثناء العدة فل يس لها أن تطل ق نفسها مرة أخ رى الا إذا كانت الوكالة ظ اهرة في الش مول لذلك، أي بأن تكون وكيل ةً في ايقاع الطلاق كلما رجع اليها الزوج في عدتها، ويكون الطلاق الثالث بائناً بل تحرم المرأة عليه على التفصيل الوارد في المادة (.)١٣٦ ثالثاً: إذا اشترطت المرأة الوكالة عن الزوج في الطلاق مع التصريح بأن لها إيقاعه خلع اً عندت وفر ش روطه -ومنه ا كراهة الزوجة للزوج كراهة ش ديدة بحيث يحملها على تهديده بعدم أداء حقوقه الزوجية -يك ون مقتضى وكالتها في هذا النحو من الطلاق أن تكون وكيل ةً أيضاً عن الزوج في قبول الفداء بعد بذلها له، ثم تطلق نفسها على ما بذلت، ويقع الطلاق بائناً وفقاً لما نصت عليه المادة (.)١٣٠"},{"n":9,"p":5,"c":"الباب الأول - الزواج › الفصل الأول - عقد الزواج","t":"يج وز للمرأة أن تشترط على الرجل في عقد الزواج أن لا يتزوج عليها وإن سمح القانون له بذلك، فيجب عليه الوفاء لها به ذا الشرط، ولك ن لو خ الف وت زوج بأخرى لم يبطل وإن كان آثم اً شرعاً.وك ذلك إذا اشترطت عليه أن لا يطلقها الا بموافقتها فإنه يص ّح الشرط ويلزمه الوفاء لها به، ولكن لو طلقها بدون موافقتها ص ّح وإن كان آثماً شرعاً."},{"n":10,"p":5,"c":"الباب الأول - الزواج › الفصل الأول - عقد الزواج","t":"إذا اشترطت عليه أن يسكنها في بلدها أو في بلد معيّن غيره أو في منزل مستقل صح الشرط ويلزمه الوفاء لها به ما لم تس قطه، ول وخ الف الشرط أثم ولكن لا يثبت لها الخيار -أي حق فسخ العقد -ب ذلك.ويج وز لها الرجوع الى القضاء لإجبار الزوج على الوفاء به، كم ا يجوز لها عدم الس كنى في غير ما اشترطته ولا تع ّد ناشزة بذلك."},{"n":11,"p":6,"c":"الباب الأول - الزواج › الفصل الأول - عقد الزواج","t":"إذا ادعى رجل زوجية امرأة فص دّقته أو ادعت امرأة زوجية رجل فص دّقها يحكم لهما بذلك مع احتمال الصدق وكون الحق لا يعدوهما."},{"n":12,"p":6,"c":"الباب الأول - الزواج › الفصل الثاني - أولياء العقد","t":"ل يس للأب والج ّد للأب ولا لغيرهما الولاية في تزويج الابن الب الغ الرش يد، فلو تزوج من دون موافقة أبيه ولا جدّه لأبيه صحّ."},{"n":13,"p":6,"c":"الباب الأول - الزواج › الفصل الثاني - أولياء العقد","t":"لا ولاية للأب والج ّد للأب ولا لغيرهما في تزويج البنت البالغة الرش يدة إذا كانت ثيباً، وأما إذا كانت باكرة -وهي التي لم تتزوج أو تزوجت ولم يدخل بها زوجها ثم انفص لت عنه -فالولاي ة في تزويجها مش تركة بينها وب ين أبيها أوج دها للأب، ف لا يص ّح تزويجها الا بموافقتها وموافقة الأب أو الج دل لأب. ومع فقدهما فأمرها بيدها، وليس لأي من أقربائها ولاية عليها في ذلك. ح الأب والج ّد للأب في تزويج البالغة الرشيدة الباكرة، فاخت ار كل منهما"},{"n":14,"p":6,"c":"الباب الأول - الزواج › الفصل الثاني - أولياء العقد","t":"إذا تشا ّ شخصاً لتزويجها وهي موافقة على كل منهما يقدّم اختيار الجدّ."},{"n":15,"p":6,"c":"الباب الأول - الزواج › الفصل الثاني - أولياء العقد","t":"تسقط ولاية الأب والج ّد للأب في تزويج الباكرة الرش يدة وتك ون الولاية لنفس ها في الحالات الآتية: اولاً: إذا منعاها من الزواج بُك ْف ِئها شرعاً وعرفاً خلافاً لمصلحتها. ثانياً: إذا اعتزلا التد ّخل في أمر زواجها مطلقاً. ثالثاً: إذا سقطا عن أهليّة الولاية لفقد العقل أو لنحو ذلك. رابعاً: إذا كانا غائبين غيبة منقطعة، فلا تتمكّن من الاتصال بأحدهما مع حاجتها الملحة للزواج."},{"n":16,"p":6,"c":"الباب الأول - الزواج › الفصل الثاني - أولياء العقد","t":"م ن بل غ عاقلاً ولكن لم يكن رش يداً -أي لا يمي زما فيه الص لاح عم اع داه -ول وفي أم ور الزواج كاختي ار الزوجة وتعي ين المهر وتحديد الش روط، ف لا بدمن أن يس تأذن أب اه أوج ده لأبيه إذا أراد الزواج، ف لا يص ّح من دون إذن أحدهما."},{"n":17,"p":7,"c":"الباب الأول - الزواج › الفصل الثاني - أولياء العقد","t":"يشترط في ولاية الأولياء العق ل، والرش د -بمعن ى تميي زما فيه ص لاح الم ولّى عليه عن غيره -كما يشترط الإسلام إذا كان المولّى عليه مسلماً."},{"n":18,"p":7,"c":"الباب الأول - الزواج › الفصل الثاني - أولياء العقد","t":"لا يشترط فيج واز تزويج الاب والجد للأب الولد غير الرش يد وجود مصلحة معينة له في ذلك، بل يكفي عدم المفسدة."},{"n":19,"p":7,"c":"الباب الأول - الزواج › الفصل الثالث - أسباب تحريم الزواج","t":"أس باب التح ريم هي الأم ور التي لا يص ّح في حال وجودها زواج الرجل بالمرأة وهي:"},{"n":20,"p":7,"c":"الباب الأول - الزواج › السبب الأول - النسب","t":"لا يصح بالنسب زواج الرجل بعدة نساء مؤبداً: اولاً: الاُم والجدة سواء كانت للأب أو للأم. ثانياً: البنت والحفيدة ولو بوسائط، كبنت البنت وبنت الابن وبنات أولادهما. ثالثاً: الاُخت لأب كانت أو لأم أو لهما. رابعاً: بنات الأخ والاُخت وحفيداتهما ولو بوسائط. خامساً: العمة ولو مع الواسطة، كعمة الأبوين والجدين وهكذا. سادساً: الخالة ولو مع الواسطة، كخالة الأبوين والجدين وهكذا."},{"n":21,"p":7,"c":"الباب الأول - الزواج › السبب الأول - النسب","t":"لا فرق فيما لا يصح من الزواج بالنسب بين النسب الشرعي وإن كان عن وطء شبه ٍة، والنسب غير الشرعي وهو ما حصل بالزناء."},{"n":22,"p":7,"c":"الباب الأول - الزواج › السبب الثاني - المصاهرة وما يلحق بها","t":"لا يصح بالمصاهرة زواج الرجل بعدة نساء مؤبداً: اولاً: زوجة الأب وكذلك الجد وإن علا كجد الأب. ثانياً: زوجة الابن وكذلك الحفيد والسبط وإن نزلا كابن الحفيد والسبط. ثالثاً: أم الزوجة وجدتها لأب أو لأم. ويحرمن المذكورات الثلاث بمجرد العقد ولو مع عدم الدخول. رابعاً: بن ت الزوجة ولو مع الواسطة بشرط الدخول بأمها، س واًء ول دتها قبل الزواج به أم بعده من غيره.أم ا مع عدم الدخول بالأم فلا يجوز الزواج بالبنت ما دامت الأم زوجة له."},{"n":23,"p":8,"c":"الباب الأول - الزواج › السبب الثاني - المصاهرة وما يلحق بها","t":"لا يجوز الجم ع بين الأخت ين في الزواج، فل وت زوج بإح دى الأخت ين لا يصح الزواج بالأخرى ما دامت الأولى في عصمته وإن لم يدخل بها."},{"n":24,"p":8,"c":"الباب الأول - الزواج › السبب الثاني - المصاهرة وما يلحق بها","t":"إذا طلّق زوجته رجعيّ اً لا يصح زواجه بأختها في ع دّتها، وإذا كان الطلاق بائناً ص ّح ذلك."},{"n":25,"p":8,"c":"الباب الأول - الزواج › السبب الثاني - المصاهرة وما يلحق بها","t":"من تزوج بامرأة لا يص ّح -قب لالانفص العنها بطلاق بائن أو ما بحكمه -أن يتزوج من بنت أخيها أو من بنت أخته امن دون إذنها، وإذا عقد عليها بغير إذنها ثم أجازت صح الزواج."},{"n":26,"p":8,"c":"الباب الأول - الزواج › السبب الثاني - المصاهرة وما يلحق بها","t":"لا يص ّح الزواج بمن تكون في عص مة رجل آخر كالمطلقة بطلاق غير ص حيح شرعاً، ولا بمن تكون في مدة العدة من الغير."},{"n":27,"p":8,"c":"الباب الأول - الزواج › السبب الثاني - المصاهرة وما يلحق بها","t":"إذا تزوج بامرأة وهي في عص مة غيره أو في مدة العدة من الغير، ف إن كان جاهلاً بالحكم أي بعدم جواز الزواج منها -أو ج اهلاً بالموض وع -أي ببطلان طلاقها مثلاً أو بكونها في العدة -لم تحرم عليه مؤب داً الا إذا كان قد دخل به ا، وأما إذا تزوجها عالماً بالحكم والموضوع فإنها تحرم عليه مؤب داً وإن لم يدخل بها."},{"n":28,"p":8,"c":"الباب الأول - الزواج › السبب الثاني - المصاهرة وما يلحق بها","t":"م ن زنى بامرأة ذات زوج حرمت عليه مؤب داً، ف لا يص ّح زواجه منها بعد انفصالها عن زوجها بموت أو طلاق أو غير ذلك."},{"n":29,"p":9,"c":"الباب الأول - الزواج › السبب الثاني - المصاهرة وما يلحق بها","t":"إذا لاط بآخر -ول وب بعض الحش فة -حرم ت عليه أب داً أم المل وط وإن علت كجدته، وبنته وإن نزلت كحفيدته، وأخته، ف لا يص ّح زواجه بأية واحدةم نهن. ولا فرق في ذلك بين كون اللائط والملوط بالغين أو غير بالغين شرعاً أو كون أحدهما بالغاً والآخر غير بالغ."},{"n":30,"p":9,"c":"الباب الأول - الزواج › السبب الثالث - الرضاع","t":"إذا أرضعت امرأة طف لاً -ذك راً أو أنثى -لغيره ا أوج بذلك حرمة الزواج بين ع دد من الذكور والإناث ممن لهم علاقة بالمرض عة وزوج المرض عة والرضيع. حرم أمور:"},{"n":31,"p":9,"c":"الباب الأول - الزواج › السبب الثالث - الرضاع","t":"يشترط في الرضاع الُم ِ ّ در اولاً: أن يكون اللبن ناتج اً من ولادة بسبب سائغ شرعاً -دون الزن اء -فل وّ الل بن من المرأة من دون ولادة أو ول دت من الزن اء فأرض عت بلبنها طف لاً لم يوجب التحريم. ثانياً: أن يكون الرضاع ليوم وليلة متى رغب الطفل فيه، أو يكون خم سعش رة رضعة متتالية مشبعة، أو يكون بمقدار أنبت اللحم وش ّد العظم عرفاً. ثالثاً: أن يكون الارتضاع بامتصاص الطفل من الثدي، فل وش رب الل بن المحل وب من المرأة لم يوجب الحرمة. رابعاً: أن يكون الحليب الذي يرتضعه الطفل من مرضعة واحدة ومنتس باً بتمامه إلى رجل واحد. خامساً: تغ ذي الطفل بالحلي ب، فل وارتض عث ُ َّم ق اء الحلي بلم يترت بأثر على تلك الرضعة. سادساً: عدم تجاوز الرضيع السنتين من عمره."},{"n":32,"p":10,"c":"الباب الأول - الزواج › السبب الثالث - الرضاع","t":"إذا تحقق الرضاع الجامع للش رائط ص ار الزوج والمرض عة أب اً وأم اً للمرتض ع، وأص ولهما أج داداً وج دات، وفروعهم ا إخوة وأولاد إخوة له، وإخوتهم ا وأخواتهما أعماماً أو عمات وأخوالاً أو خالات له.وص ار المرتض ع ابن اً أو بنت اً لهما وفروعه أحفاداً لهما."},{"n":33,"p":10,"c":"الباب الأول - الزواج › السبب الثالث - الرضاع","t":"لا فرق في نشر الحرمة بالرضاع بين ما إذا كان الرضاع سابقاً على عقد الزواج وما إذا كان لاحقاً له، فينفسخ العقد في الحالة الثانية."},{"n":34,"p":10,"c":"الباب الأول - الزواج › السبب الثالث - الرضاع","t":"إذا أرضعت المرأة طف لاً لزوج بنتها -س واء أكان الطفل من بنتها أم من ض ّرتها – رض اعاً واج داً لش روط نشر الحرمة بطل عقد البنت وحرمت على زوجها مؤبّداً."},{"n":35,"p":10,"c":"الباب الأول - الزواج › السبب الثالث - الرضاع","t":"إذا أرضعت زوجة الرجل بلبنه طف لاً لزوج بنته -س واء أكان الطفل من بنته ضرتها -بطل عقد البنت وحرمت على زوجها مؤبّداً. أم من ّ"},{"n":36,"p":10,"c":"الباب الأول - الزواج › السبب الثالث - الرضاع","t":"إذا أرضعت المرأة طفلاً لابنها لم يبطل عقد الابن على زوجته ولم تحرم علي ه. ويترت ّ بعليه سائر الآث ار كحرمة المرتض ع أو المرتض عة على أولاد ع ّمه وع ّمته. زوج بغير المس لمة الا الكتابية كالمس يحية، كم الا يجوز"},{"n":37,"p":10,"c":"الباب الأول - الزواج › السبب الرابع - عدم الإسلام","t":"لا يجوز للمسلم أن يت ّ تتزوج بغير المسلم مطلقاً. للمسلمة أن ّ"},{"n":38,"p":10,"c":"الباب الأول - الزواج › السبب الرابع - عدم الإسلام","t":"لا يجوز للمسلم أو المسلمة أن يتزوج بعض المنتحلين لدين الإسلامم ّمن يحكم بك ونهم غير مس لمين كبعض الغ لاة ممن يعتقد في بعض البشر بما يتن افى مع الإقرار بالشهادتين (أشهد الا إله الا الله وأشهد أن محمداً رسول الله)."},{"n":39,"p":11,"c":"الباب الأول - الزواج › السبب الرابع - عدم الإسلام","t":"إذا خرجت الزوجة عن دين الإسلام -س واء كان خروجها عن ملة أو فطرة -فإن وقع ذلك بعد الدخول يتوق فبط لان زواجها على عدم رجوعها الى الإسلام قبل انقضاء العدة.وهكذا إذا خرج الزوج عن دين الإسلام عن مل ة، فإنه لا يبطل زواجه إذا رجع الى الإسلام قبل انقضاء عدة المرأة."},{"n":40,"p":11,"c":"الباب الأول - الزواج › السبب الرابع - عدم الإسلام","t":"إذا خرج الزوج عن دين الإسلام عن فطرة بطل زواجهما ووج بعلى زوجته أن تعتد عدة الوفاة، وإذا رجع الى الإسلام يمكنه تجديد العقد عليها."},{"n":41,"p":11,"c":"الباب الأول - الزواج › السبب الرابع - عدم الإسلام","t":"المقصود بمن خرج عن دين الإسلام عن فطرة هو من ولد وأحد أبويه أو كلاهما مس لم ثم اخت ار غير الإسلام، والمقص ود بمن خرج عن دين الإسلام عن ملة هو من ولد وأبواه غير مسلمين ثم أسلم ثم خرج عن الإسلام."},{"n":42,"p":11,"c":"الباب الأول - الزواج › السبب الخامس - استيفاء العَدد وما يلحق به","t":"من كانت عنده أربع زوجات تحرم عليه الخامسة ما دامت الأرب ع في عص مته، ولو طلق إحداهن َّ رجعياً لم يجز له الزواج بأخرى إلا بعد خروجها من العدة. ولو طلق زوجته ثلاثاً لا يجوز له الزواج منها حتى تتزوج من غيره كما نصت عليه المادة (١٣٦)وما بعدها، ولو طلق زوجته تسعاً لا يجوز له الزواج منها أبداً كما نصت عليه المادة (.)١٤٠"},{"n":43,"p":11,"c":"الباب الأول - الزواج › السبب السادس - اللعان وما بحكمه","t":"اللعان مباهلة خاصة بين الزوجين فيما إذا رمى الزوج زوجته بالزنى أو نفى أن ينتسب إليه من ولدته مع لحوقه به ظ اهراً.وإذا تم اللع ان بش روطه ينفس خ عقد الزواج بين الطرفين وتحرم المرأة على الرجل مؤبداً."},{"n":44,"p":11,"c":"الباب الأول - الزواج › السبب السادس - اللعان وما بحكمه","t":"إذا قذف الزوج امرأته الخرساء أو الص ّماء بالزنى حرمت عليه مؤبداً."},{"n":45,"p":12,"c":"الباب الأول - الزواج › السبب السابع - الإحرام","t":"يحرم الزواج في حال التلبس بإحرام الحج أو العمرة، ويبطل العقد حتى مع جهل الرجل المحرم بالحكم، وأما مع علمه به فتحرم المرأة عليه مؤبداً."},{"n":46,"p":12,"c":"الباب الأول - الزواج › الفصل الرابع - المهر","t":"المه ر: ويس مى الص داق أيض اً، وه وما تس تحقه الزوجة بجعله في العقد أو بتعيينه بعده ويعبّر عن عنه ب(المهر المسمى)، أو ما تستحقه بسبب الدخول بالمرأة أو ما بحكمه، ويعبر عنه ب(مهر المثل)."},{"n":47,"p":12,"c":"الباب الأول - الزواج › الفصل الرابع - المهر","t":"كل ما يملكه المسلم وتكون له مالية عند الناس يصح أن يجعل مه راً، عين اً كان أو ديناً أو منفعة."},{"n":48,"p":12,"c":"الباب الأول - الزواج › الفصل الرابع - المهر","t":"لا يتقدر المهر قلة ولا كثرة، ولا بد أن يكون متعيناً، فلو كان مجهولاً تماماً بطل المهر وص ّح العقد ويكون للمرأة مع الدخول مهر المثل."},{"n":49,"p":12,"c":"الباب الأول - الزواج › الفصل الرابع - المهر","t":"إذا ا ُ ِ ّج لالمهر -ك لاً أو بعض اً -وج بتعي ين الأجل بما يرف ع الإبه ام التام -كتحديده بأقرب الأجلين أو عند القدرة والمطالبة، -فلو كان الأجل مبهم اً بحتاً -كمضي مدة ما صح العقد وصح المهر وسقط التأجيل."},{"n":50,"p":12,"c":"الباب الأول - الزواج › الفصل الرابع - المهر","t":"إذا كان المهر شيئاً معين اً فوج دت المرأة به عيب اً فإن رض يت به فه و، والا كان لها ردّه بالعيب والمطالبة ببدله من المثل أو القيمة."},{"n":51,"p":12,"c":"الباب الأول - الزواج › الفصل الرابع - المهر","t":"إذا أهملا ذكر المهر في العقد صحّ، فإن اتفقا بعده على شيء تع ين مه راً وكان كالمذكور فيه، والا فإن دخل بها استحقت عليه مهر مثلها، ويلاح ظ في مق داره حال المرأة وصفاتها من السن والبكارة والجمال والشرف وغير ذلك.وإن طلقها قبل الدخول استحقت عليه أن يعطيها شيئاً بحسب حاله من الغنى والفقر واليسار ق ش يئاً. أمر غير الطلاق لم تس تح ّ والإعس ار.ول وانفص لا قبل الدخول بٍ وكذا لو مات أحدهما."},{"n":52,"p":13,"c":"الباب الأول - الزواج › الفصل الرابع - المهر","t":"إذا كان المهر كله أو بعضه ّ حالاً فللزوجة الامتناع عن تمكين الزوج من الدخول بها قبل قبض ما كان ّ حالاً."},{"n":53,"p":13,"c":"الباب الأول - الزواج › الفصل الرابع - المهر","t":"تستحق المرأة المهر المسمى بالعقد، ويس قط نص فه قبل الدخول أو ما بحكمه بالطلاق، وكذلك مع موت أحد الزوجين قبل الدخول فإنها تستحق نصف المهر."},{"n":54,"p":13,"c":"الباب الأول - الزواج › الفصل الرابع - المهر","t":"يص ّح أن يشترط الزوج في عقد الزواج أن يكون هو -مثلاً -وكيلاً عن الزوجة في إب راء ذمته مما يبقى عليه من مهرها وفي تملي كنفسه ما يع ود اليها من ممتلكات عينية مشتراة بالمهر او مه داة اليها من قبله أو من قبل أقربائه عند الزواج فيما إذا اضطر الى طلاقها في ح الات معينة، كس وء عش رتها بح ّد يص عب تحمل هج داً، أو مع تب ين اص ابتها من قبل الزواج بم رضم زمن يخ ّل بالحياة الزوجية والعيش المشترك -ومنه بعض الأمراض النفسية كالكآبة الحادة المثبتة طبياً -أو هجرها لبيت الزوجية من دون ع ذر مقب ولم دة غير قص يرة، أو ممارستها لبعض الفواحش كالزنا والس حاق، أو مجاهرته اب بعض المنك رات والمحرمات في الملأ العام."},{"n":55,"p":13,"c":"الباب الأول - الزواج › الفصل الرابع - المهر","t":"إذا اختلف الزوجان في مق دار المهر كان القول ق ول الزوج بيمينه الا أن تثبت الزوجة دعواها ببينة أو نحوها.وهك ذا إذا ادعت الزوجة أنّ عين اً دار -مه ر لها وأنكر الزوج ذلك، ف إن القول قوله بيمينه معينة -ك ٍ ما لم تقم البينة."},{"n":56,"p":13,"c":"الباب الأول - الزواج › الفصل الرابع - المهر","t":"إذا ادعى الزوج تس ليم المهر الى الزوجة وأنك رت ذلك ولا بينة له فالقول قولها بيمينها."},{"n":57,"p":13,"c":"الباب الأول - الزواج › الفصل الخامس - العيوب","t":"العيوب التي توجب خيار الفسخ قد تكون في الزوج وقد تكون في الزوجة."},{"n":58,"p":14,"c":"الباب الأول - الزواج › الفصل الخامس - العيوب","t":"العيوب في الزوج التي توجب الخيار للزوجة في فسخ عقد الزواج أربعة: اولاً: الجنون وإن طرأ بعد العقد والدخول. ثانياً: الع نن -وه والم رض الم انع من انتص اب العضو الذكري بحيث يعجز الرجل عن الإي لاج، ولا يثبت الخيار به في الط ارئ منه بعد الدخول، وكذلك إذا تمكن من الدخول بامرأة أخرى. ثالثاً: الخصاء -وهو نزع الخصيتين -إذا كان سابقاً على العقد. الجب -وهو قطع العضو الذكري بحيث لم يب ق منهما يمكنه به الدخول، رابعاً: ّ ولا يثبت الخيار به في الطارئ منه بعد الدخول."},{"n":59,"p":14,"c":"الباب الأول - الزواج › الفصل الخامس - العيوب","t":"العيوب في الزوجة التي توجب الخيار للزوج في فسخ العقد إذا كانت سابقة عليه سبعة: اولاً: الجنون. ثانياً: الجذام. ثالثاً: البرص. رابعاً: القرن، وهو ما يكون في فرج المرأة ويمنع من إيلاج العضو الذكري فيه. خامساً: الإفضاء، بمعنى اتحاد مسالك البول والحيض والغائط كلاً أو بعضاً. سادساً: العمى. سابعاً: العرج البيّن وإن لم يبلغ حد الإقعاد."},{"n":60,"p":14,"c":"الباب الأول - الزواج › الفصل الخامس - العيوب","t":"يس قط خي ار العي بفي كلمن عي وب الرجل والم رأة مع الت أخير في الفسخ بأزيد من المقدار المتعارف بعد العلم بثبوت العيب وثبوت الخيار بسببه.فلو أ ّخر الفسخ لانتظار حضور من يستشيره في ذلك -مثلاً -فإن لم يكن التأخير بح ّد يع ّد في العرف توانياً في إعمال الخيار لم يسقط والا سقط."},{"n":61,"p":14,"c":"الباب الأول - الزواج › الفصل الخامس - العيوب","t":"ليس العقم من العيوب الموجبة للخيار في طرف الرجل ولا في طرف المرأة."},{"n":62,"p":15,"c":"الباب الأول - الزواج › الفصل الخامس - العيوب","t":"لا مهر للزوجة مع فسخ الزوج بعيب فيها قبل الدخول، ولها تمام المهر المسمى بعده إذا لم تكن قد دلّست ولو بسكوتها عن العي بمع إق دام الرجل على الزواج منها بارتك از الس لامة منه.وله ا تمام المهر مع فس خها بعي بفي الرجل إن كان بعد الدخول، وأما إن كان قبله فلا تستحق شيئاً الا في العنن فإنها تستحق نصف المهر."},{"n":63,"p":15,"c":"الباب الأول - الزواج › الفصل الخامس - العيوب","t":"لا يثبت الخيار للزوجة بمجرد ثبوت عنن الزوج -بخلاف الحال في بقية عي وب الرجل -بل لا بد بعد ثبوته من أن ترفع أمرها الى القاضي، فيمهل ه سنة كاملة من حين المرافعة ليع الج نفسه، ف إن لمي تمكن من الدخول بها خلالها كان لها فسخ العقد."},{"n":64,"p":15,"c":"الباب الأول - الزواج › الفصل الخامس - العيوب","t":"يص ّح زواج المريض في المرض المتّصل بموته بشرط الدخول، فإذا لم يدخل بها حتّى مات في مرضه بطل العقد ولا مهر للمرأة ولا ميراث ولا عدّة عليها بموت ه، والمقص ود بم رض الموت هو خص وص المرض الذي يكون معه في مع رض الموت لا المرض غير الخطير الذي اتفق الموت به على خلاف العادة."},{"n":65,"p":15,"c":"الباب الأول - الزواج › الفصل السادس - الحقوق الزوجيّة","t":"حقّوق الزوج على الزوجة هي: أولاً: تمكينه من الجماع وغيره من الممارس ات الزوجية المتعارفة وعدم منعه عنها ّإلا لعذر مقبول شرعاً، ككونها في أي ام الح يض أو النف اس أو تض ررها ضرراً معتداً به بسبب الجماع مثلاً. ويص ّح أن تشترط في عقد الزواج أن لا يلزمها بالجماع ونحوه ولا يمارسه الا بموافقتها، فيلزمه الوفاء به. ثانياً: أن لا تخرج من بي تس كناها من دون إذنه، إلا لحاجة ض رورية كالعلاج أو نحوه مما تتضرر أو تقع في حرج بالغ بتركه، أو يتوقف عليه أداء واجب كحجة الإسلام.ويل زم الزوج الإذن لها بزي ارة أقربائها ونحو ذلك بالمق دار الذي يقتضيه الإمساك بالمعروف.ويكفي في احراز الإذن ظه ور حال الزوج في الموافقة على خروجها لمثل ذلك من الأغراض الصحيحة. وإذا اشترطت في عقد الزواج -مثلاً -أن تكون مأذونة في الخروج للدراسة أو للعمل أو لغير ذلك مما لا منع منه شرعاً ص ّح الشرط، فليس للزوج منعها من الخروج وفق ذلك. ثالثاً: أن لا تؤذيه ولا تسخطه ولا تنفّره عن نفسها بتصرفاتها غير اللائقة."},{"n":66,"p":16,"c":"الباب الأول - الزواج › الفصل السادس - الحقوق الزوجيّة","t":"لا يستحق الزوج على الزوجة القيام بالأعمال المنزلية كالتنظيف وإع داد الطع ام وغسل الملابس ونحو ذلك، الا إذا صرح بذلك في ضمن عقد الزواج او كان من المتعارف في محيطهما الاجتماعي قيام الزوجة بتلك الأعم الوج رى العقد مبني اً على ذلك وان لم يتم التصريح به."},{"n":67,"p":16,"c":"الباب الأول - الزواج › الفصل السادس - الحقوق الزوجيّة","t":"حقّوق الزوجة على الزوج هي: أولاً: أن ينفق عليها بالغ ذاء واللب اس والمس كن والع لاج وس ائر ما تحتاج إليه بحسب حالها بالقياس إليه. ثانياً: أن يعاشرها بالمعروف فلا يؤذيها ويعتدي عليها ويعاملها بخشونة من دون مبرر. ثالثاً: أن لا يهجرها رأساً ويجعلها كالمعلّقة لا هي ذات زوج ولا هي مطلّقة. رابعاً: أن لا يترك المعاش رة الزوجية معها -بالجم اع ونحوه -م ن دون ع ذر إذا ع ّد تركها إض راراً بها، ب لوإن لم يع ّد إض راراً إذا كان الترك لأزيد من أربعة أشهر الا أن يكون ذلك برضاها، أو مع اشتراطه عليها حين العقد. خامساً: أن يبيت عندها ليلة من كل أربع لي ال، س واًء كان عن ده زوجة غيرها أم لم يكن.والمبي ت الواجب هو الذي يكون مبني اً على الإين اس وحسن المعاش رة بالوجه المتعارف، ولا يكفي ما يبتني منه على الهجر والاعراض والنفرة."},{"n":68,"p":17,"c":"الباب الأول - الزواج › الفصل السابع - أحكام النشوز","t":"إذا نشزت الزوجة بتركها بيت الزوجية من دون إذن الزوج لم تستحق النفقة عليه، وهك ذا مع عدم تمكينه مطلق اً من الجماع ونحوه من دون ع ذر وإن لم تخرج من عنده.وللزوج رفع أمره الى القاضي لإلزامها بترك النشوز وأداء حقوقه الزوجية."},{"n":69,"p":17,"c":"الباب الأول - الزواج › الفصل السابع - أحكام النشوز","t":"إذا منع الزوج زوجته من حقوقها الواجبة لها يمكنه ارف ع أمرها الى القاضي لإلزامه بأدائها، وليس لها هجره ولا التعدي عليه."},{"n":70,"p":17,"c":"الباب الأول - الزواج › الفصل السابع - أحكام النشوز","t":"إذا امتنع الزوج عن الانفاق على زوجته فطالبته بالطلاق فامتنع منه أيضاً فلها أن ترفع أمرها إلى القاضي فيطالبه بالقيام بأحد أمرين: إم ا الانفاق أو الط لاق، فإذا لم يستجب ولم يمكن إلزامه بذلك يجوز للقاضي أن يطلقها استجابة لطلبها، فينشئ الطلاق بصيغته الشرعية بقوله(: فلانة زوجة فلان طالق)."},{"n":71,"p":17,"c":"الباب الأول - الزواج › الفصل السابع - أحكام النشوز","t":"إذا هجر الزوج زوجته هج راً تام اً -وإن لم يترك الإنف اق عليها -فص ارت كالمعلقة لا هي ذات زوج ولا هي مطلقة جاز لها رفع أمرها الى القاضي، فيطلب من الزوج القي ام بأحد أمرين إما الع دول عن هجرها أو تس ريحها بالطلاق، فإذا امتنع منهما جميعاً ولم يمكن إلزامه جاز للقاضي أن يطلقها بطلبها ذلك. يكف عن ذلك"},{"n":72,"p":17,"c":"الباب الأول - الزواج › الفصل السابع - أحكام النشوز","t":"إذا كان الزوج يعتدي على زوجته بالضرب أو غيره بلا مبرر ولا ّ جاز لها رفع أمرها الى القاضي لإلزامه بالمعاشرة بالمعروف، فإن امتنع ورفض في الوقت نفسه طلاقها جاز للقاضي أن يطلقها استجابة لطلبها."},{"n":73,"p":17,"c":"الباب الأول - الزواج › الفصل السابع - أحكام النشوز","t":"اولاً: إنما يكون للقاضي إيق اع الطلاق في الح الات الثلاث المتقدمة في المواد (٧٢)، ٧١، ٧٠فيم ا إذا ثبت له من خ لال ش هادات موثقة ونحوه اص دق الزوجة فيما تدعيه من تقصير الزوج في الوفاء بالحقوق الثابتة لها بأحد الوجوه المتقدمة، من دون تقصير منها في أداء الحقوق الثابتة له. ثانياً: يش ترط موافقة المرجع الديني على إيق اع الطلاق في الح الات الثلاث المتقدمة. ثالثاً: ل يس للقاضي أن يطلق الزوجة من دون ثبوت تقصير الزوج وامتناعه عن الالتزام برعاية حقوقها ورفض طلاقها في الوقت نفسه، كما أنه ليس له طلاقها في غير الحالات الثلاث المتقدمة وإن طلب تهي ذلك لتعسر الحي اة الزوجية بين الطرفين، كم ا إذا كانت الزوجة تك ره الزوج ولا تريد الع يش معه بالرغم من استعداده لأداء حقوقها الزوجية كاملة. والطريق الوحيد لتحقيق رغبة الزوجة في الانفصال عن الزوج في مثل ذلك يكون بإقناعه بالطلاق ولو خلع اً معت وفر ش روطه، الا إذا كانت الزوجة وكيلة عن الزوج في طلاق نفسها – كما نصت عليه المادة (-)٨فإنه يجوز لها أن تجري الطلاق وفق ذلك."},{"n":74,"p":18,"c":"الباب الأول - الزواج › الفصل السابع - أحكام النشوز","t":"اولاً: المقص ود بالمرجع الديني في البند (ثاني اً) من المادة (٧٣)وف ي جميع المواد الآتية في هذه المدونة -ه والمرجع الديني الأعلى -أي من يقل ده أكثر الشيعة في العراق -إن وجد، والا فأشهر المراجع المعروفين بالفقاهة والعدالة في النجف الأشرف. ثانياً: يقوم المجلس العلمي في ديوان الوقف الشيعي وفقاً لطل بمح اكم الأح وال الشخصية بالتواصل مع المرجع الديني لاستحصال موافقته فيما تشترط فيه من مواد هذه المدونة. ثالثاً: إذا تصدى المرجع الديني لممارسة شيء من الصلاحيات الممنوحة للقاضي في مواد هذه المدونة -وهي له في الأساس بحسب الفقه الجعفري -ووث ّ ق ذلك بكتاب صادر منه أو من مكتبه يلت زم بمقتض اه من قبل قاضي محكمة الأحوال الشخصية."},{"n":75,"p":18,"c":"الباب الأول - الزواج › الفصل الثامن - أحكام الإلحاق بالنسب","t":"يلحق ولد المرأة -ذك راً كان أو أنثى -بزوجه ا مع دخوله بها واحتم الإن زال المني في داخل المهبل، أو تحقق الإنزال على ظاهره من دون دخول بحيث يحتمل حمله امنه، ومض يس تة أشهر من حين تحقق الدخول أو ما بحكمه الى حين الولادة."},{"n":76,"p":19,"c":"الباب الأول - الزواج › الفصل الثامن - أحكام الإلحاق بالنسب","t":"إذا تحقق شرط الحاق الولد بالزوج فليس له نفيه عن نفسه حتى مع ثبوت زناء المرأة فضلاً عما لو كانت متهمة به من دون اثبات. ويستثنى من ذلك ما إذا كانت هناك طريقة علمية بيّنة -كما هو المع روف بش أن فحص الحمض النووي (-)DNAوت ّم التأك دمن إجرائها بص ورة ص حيحة فإنه يمكن التعويل عليها إذا كشفت عن عدم كون الزوج أباً للولد، فيجوز له أن ينفيه عن نفسه."},{"n":77,"p":19,"c":"الباب الأول - الزواج › الفصل الثامن - أحكام الإلحاق بالنسب","t":"لا يجوز تبنّي ولد الغير، بمعن ى أن يلحق بغير أبويه وينس بالى من لم يتولد منه، ولا أثر للتبني شرعاً في وجوب النفقة أو حرمة الزواج أو ثبوت الميراث أو غيرها من الأحكام. ولكن لام انع من أن يتكف لغير الأبوين بحض انة الولد وتربيته والانف اق عليه ونحو ذلك بموافقة منهما مع اقتضاء مصلحته ذلك.وكذلك لا مانع منه مع فقدان الأبوين بإذن القاضي."},{"n":78,"p":19,"c":"الباب الأول - الزواج › الفصل الثامن - أحكام الإلحاق بالنسب","t":"م ن زنى بامرأة فول دت منه يثبت بينه وب ين الولد جميع آث ار الأب وة والبن وة ع دا الت وارث فإنهم الا يتوارث ان، وهك ذا الح الفي ثبوت آث ار الأمومة والبن وة بين المرأة الزانية والولد ما عدا التوارث."},{"n":79,"p":19,"c":"الباب الأول - الزواج › الفصل الثامن - أحكام الإلحاق بالنسب","t":"إذا ادعى رجل أو امرأة بنوة ولد صغير -ذكراً كان أو أنثى -وكان الولد مجهول النسب ولا ينازع المدعي فيه منازع يصدق في دعواه ولا يلتفت الى انك ار الولد بعد بلوغه ورشده، الا أن ينكشف بطريقة علمية بينة -كم ا هو المع روف بش أن فحص الحمض النووي ()DNAعدم انتسابه اليه."},{"n":80,"p":19,"c":"الباب الأول - الزواج › الفصل التاسع - أحكام إرضاع الولد وحضانته","t":"الأ ُ ّم أح قّ بإرض اع ول دها من غيرها، فل يس للأب تعي ين غيرها لإرض اع الولد أو إرض اعه بالحلي بالص ناعي ّإلا إذا طالب تب أجرة وكان يتيسر له إرض اعه على وجه آخر بكلفة أقل أو بدون كلفة. ويستثنى من ذلك ما إذا كانت مصلحة الولد تقتضي أن يرتض ع من لبن أمه وطالبت الأم بالأجرة المتعارفة وكان للولد مال او لم يكن له مال ولكن كان الأب موسراً، فإنه يتعين عليه عندئذ ايكال الإرضاع اليها ودفع الأجرة لها."},{"n":81,"p":20,"c":"الباب الأول - الزواج › الفصل التاسع - أحكام إرضاع الولد وحضانته","t":"حضانة الولد وتربيته وما يتعلّق بها من مصلحة حفظه ورعايته تكون في مدّة حق الأم، وتبقى لها الى أن يبلغ الولد سبع الرضاع – وهي حولان كاملان -من ّ سنوات -ذكراً كان أو أنثى -ثم تكون الحضانة للأب إلى آخر مدتها."},{"n":82,"p":20,"c":"الباب الأول - الزواج › الفصل التاسع - أحكام إرضاع الولد وحضانته","t":"يجب على من تكون له الحضانة من الأبوين أن يوفّر للآخر فرصة اللق اء بول ده والتواصل معه بالمقدار المناسب وفي المكان اللائق بشأنه، وإذا وقع الاختلاف بينهما في الأمر تولى القاضي تحديد ذلك زماناً ومكاناً حسب ما تقتضيه مصلحة الأطراف الثلاثة."},{"n":83,"p":20,"c":"الباب الأول - الزواج › الفصل التاسع - أحكام إرضاع الولد وحضانته","t":"إذا افترق الأبوان بطلاق أو ما بحكمه قبل أن يبلغ الولد سبع سنوات لم يس قط حق الأم في حض انته ما لم تتزوج من رجل آخر، ف إذا تزوج تس قط حقها في الحضانة وص ارت للأب.ول وفارقها الزوج الثاني لم تثبت لها الحضانة مرة أُخرى. ّ ي"},{"n":84,"p":20,"c":"الباب الأول - الزواج › الفصل التاسع - أحكام إرضاع الولد وحضانته","t":"إذا مات الأب بعد اس تحقاقه لحض انة الولد فالأ ُ ّم أح ّ ق بحض انته من الوص ّ أتزوجت أم لا.وإذا ماتت لأبيه ومن جدّه وجدّته له وغيرهما من أقاربه سواء ّ الأ ُ ّم في زمن حضانتها صارت الحضانة للأب وليس لوصيّها ولا لأبيها ولا لأ ُ ّمها حق في ذلك. فضلاً عن باقي أقاربها ّ"},{"n":85,"p":20,"c":"الباب الأول - الزواج › الفصل التاسع - أحكام إرضاع الولد وحضانته","t":"إذا فقد الأبوان أو فقدا الأهلية فالحضانة للج ّد من طرف الأب، فإذا فقد ولم يكن حق الحضانة لأق ارب الولد على ترتي بمرات بالإرث، له وصي ولا للأب يثبت ّ ّ الأقرب منهم يمنع الأبعد. ق الحضانة من الأبوين أو غيرهما أن يكون عاقلاً مأموناً"},{"n":86,"p":20,"c":"الباب الأول - الزواج › الفصل التاسع - أحكام إرضاع الولد وحضانته","t":"يشترط فيمن يثبت له ح ّ على سلامة الولد، وأن يكون مسلماً إذا كان الولد محكوماً بالإسلام. وإذا لم يكن يقوم بواج بالحضانة ويتض رر الولد بذلك -ولا سيما إذا كان يتع رض عن ده للعن فالمتك رر أو يس يء تربيته -ج از رفع الدعوى عليه عند القضاء، فيلزمه القاضي برعاية واجب ات الحضانة وت أمين مصلحة الول د، فإن تخلّ فعن ذلك انت زع الولد منه وأوك لحض انته الى من يص لح لذلك من الأبوين أو غيرهما."},{"n":87,"p":21,"c":"الباب الأول - الزواج › الفصل التاسع - أحكام إرضاع الولد وحضانته","t":"يجوز لكل من الأبوين التن ازل عن حق الحضانة للآخر بالنسبة إلى تمام مدة الحضانة أو بعضها.ولا يجوز له التنازل إلى غيره."},{"n":88,"p":21,"c":"الباب الأول - الزواج › الفصل التاسع - أحكام إرضاع الولد وحضانته","t":"تنته ي الحضانة ببل وغ الولد رش يداً -ف إذا وص لإلى سّن البل وغ وكان رشيداً -بحيث يميز ما فيه الصلاح عن غيره -لم يكن لأحد حق الحضانة عليه حتى الأبوين، بل هو مالك لنفسه -ذكراً كان أو أنثى -فله الخيار في الانض مام الى من يشاء منهما أو من غيرهما."},{"n":89,"p":21,"c":"الباب الأول - الزواج › الفصل العاشر - النفقات","t":"تجب على الشخص نفقة الغير بسببين: الزوجية والقرابة:"},{"n":90,"p":21,"c":"الباب الأول - الزواج › السبب الأول - الزوجية","t":"تثبت نفقة الزوجة على الزوج وفقاً لما نصت عليه المادة (٦٧)من هذه المدونة وتسقط مع نشوزها وفقاً لما نصت عليه المادة (٦٨)منها."},{"n":91,"p":21,"c":"الباب الأول - الزواج › السبب الأول - الزوجية","t":"تثب ت النفقة للمطلقة ذات الع دّة الرجعيّة ما دامت في الع دّة، م ن غير فرق بين كونها حاملاً أو غير حامل."},{"n":92,"p":21,"c":"الباب الأول - الزواج › السبب الأول - الزوجية","t":"لا نفقة للمطلقة الرجعية إذا كان طلاقها في حال نش وزها، وإذا رجعت عن النشوز قبل انقضاء عدتها استحقت النفقة، كما إذا نشزت بترك بيت الزوجية فطلقها زوجها ثم رجعت إليه قبل انته اء العدة، فإنه ا تستحق النفقة للمدة الباقية."},{"n":93,"p":22,"c":"الباب الأول - الزواج › السبب الأول - الزوجية","t":"تس قط نفقة ذات الع دّة البائنة -س واء أكانت عن طلاق أم فسخ ّ -إلا إذا كانت عن طلاق وكانت حاملاً فإنّها تستحقّ النفقة والسكنى حتّى تضع حملها."},{"n":94,"p":22,"c":"الباب الأول - الزواج › السبب الأول - الزوجية","t":"الضابط في النفقة شرعاً هو توفير ما تحتاج إليه الزوجة في معيشتها من الطعام والكسوة والمسكن وأثاث المنزل وغير ذلكم ّما يليق بشأنها بالقياس إلى زوجها، ويختل فذلك نوع اً وك ّماً وكيف اً بحسب اخ تلاف الأمكنة والأزمنة والح الات والأعراف والتقاليد."},{"n":95,"p":22,"c":"الباب الأول - الزواج › السبب الأول - الزوجية","t":"ل يس من النفقة الواجب بذلها للزوجة ما تش تغل بهذ ّمته ام ّما تس تدينه لغير نفقتها، وم ا تنفقه على من تجب نفقته عليها، وم ا يثبت عليها من فدية أو كفّارة أو دية جناية ونحو ذلك."},{"n":96,"p":22,"c":"الباب الأول - الزواج › السبب الأول - الزوجية","t":"إذا لم تحص لالزوجة على النفقة الواجبة لها كّلاً أو بعض اً كّم اً أو كيف اً، لفقر الزوج أو امتناعه بقي ما لم تحص له منها دين اً فيذ ّمته، فل وم ات أُخ رج من أصل تركته كسائر ديونه، ولو ماتت انتقل إلى ورثتها كسائر تركتها."},{"n":97,"p":22,"c":"الباب الأول - الزواج › السبب الأول - الزوجية","t":"نفق ة الزوجة تقبل الإس قاط سواء بالنسبة إلى الزم ان الحاضر أم بالنسبة إلى الأزمنة المستقبلة."},{"n":98,"p":22,"c":"الباب الأول - الزواج › السبب الأول - الزوجية","t":"لا يعتبر في استحقاق الزوجة النفقة على زوجها فقرها وحاجتها، ب لتس تحقها وإن كانت متمكنة مالياً."},{"n":99,"p":22,"c":"الباب الأول - الزواج › السبب الأول - الزوجية","t":"إذا لم يكن عند الزوج ما ينفقه على زوجته وجب عليه تحصيله بالتكسب اللائق بشأنه وحاله، وإذا لم يكن متمكن اً منه لم يجب عليه تحص يله بمث لالاس تعطاء، ولكن يجب عليه الاقت راض له إذا تمكن منه من دون ح رج ومش قة مع تيسر الوفاء لاحقاً."},{"n":100,"p":22,"c":"الباب الأول - الزواج › السبب الأول - الزوجية","t":"يج وز أن يشترط الزوج في عقد الزواج أن تش ارك الزوجة من مالها -كراتبها -في الانفاق عليه أو على اولادهما، فيلزمها الوفاء بذلك."},{"n":101,"p":23,"c":"الباب الأول - الزواج › السبب الثاني - القرابة","t":"يثب ت للأب وين ح قّ الإنف اق على ابنهما -ذك راً كان أو أنثى، -كم ا يثبت ق الإنف اق على أبيه -ويش ترط في ثبوته ق درة للولد -ذك راً كان أو أُنثى -ح ّ المنف ق عليه، ف لا يثبت حق الإنف اق على المعسر الذي لا يتيسر لهت أمين ما يزيد على نفقة نفسه وزوجته. ق الإنف اق للأب وين"},{"n":102,"p":23,"c":"الباب الأول - الزواج › السبب الثاني - القرابة","t":"م ع فقد الولد -ذك راً كان أو أنثى -أو إعساره يثبت ح ّ على أولاد أولادهما أي أبناء الأبناء والبنات وبناتهم الأقرب فالأقرب. ق الإنفاق للولد مع فقد الأب أو إعساره على جدّه لأبيه وإن علا الأقرب"},{"n":103,"p":23,"c":"الباب الأول - الزواج › السبب الثاني - القرابة","t":"يثبت ح ّ فالأقرب، ومع فقده أو إعساره فعلى أ ُ ّمه، وم ع فق دها أو إعس ارها فعلى أبيها وأُ ّمها وأبي أبيها وأ ُ ّم أبيها وأبي أ ُ ّمها وأ ُ ّم أ ُ ّمها وهكذا الأقرب فالأقرب. حق الإنف اق لغير العم ودين -الآب اء والأبن اء -م ن الإخوة والأخوات"},{"n":104,"p":23,"c":"الباب الأول - الزواج › السبب الثاني - القرابة","t":"لا يثبت ّ والأعمام والع ّمات والأخوال والخالات وغيرهم."},{"n":105,"p":23,"c":"الباب الأول - الزواج › السبب الثاني - القرابة","t":"يشترط في وجوب الإنف اق على القري بفق ره، ول وكان ق ادراً على الاكتس اب بما يليق بشأنه وقد تركه طلباً للراحة لم يجب الانفاق عليه. ق الإنف اق كون الُم ْنفَ ق عليه مس لماً، ولا كون هذا علّ ٍة"},{"n":106,"p":23,"c":"الباب الأول - الزواج › السبب الثاني - القرابة","t":"لا يشترط في ثبوت ح ّ من عمى وغيره، كم الا يشترط فيه كم الالمن ِف قب البلوغ والعق ل، فيج ب على ولي غير الكامل أن ينفق من ماله على من يثبت له حق الانفاق عليه."},{"n":107,"p":23,"c":"الباب الأول - الزواج › السبب الثاني - القرابة","t":"ل يس من الانفاق الواجب للقري بب ذل مص اريف زواجه من المهر وغي ره، كما أنه ليس منه أداء ديونه ولا دفع ما ثبت عليه من فدية أو كف ارة أو دية جناية أو نحو ذلك، بل الواجب توفير ما يقيم حياته من طع ام وكس وة ومس كن وغيرهما مع ملاحظة حاله وشأنه نظير ما تقدم في نفقة الزوجة."},{"n":108,"p":24,"c":"الباب الثاني - الطلاق","t":"الط لاق: ه وانش اء الفرقة وقط ع العلقة الزوجية، وه ومن الإيقاع ات، فيكفي فيه الإنشاء من الزوج، ولا يحتاج إلى قبول الزوجة. شروط المط ِلّق"},{"n":109,"p":24,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"يش ترط في المطلّ ق: العق لوالقصد والاختي ار، ف لا يصح طلاق المجن ون ولا الس اهي واله ازل ولا طلاق الس كران ونحوه ممن لا قصد له معتد به، كما لا يصح طلاق المكره وإن تعقّب برضاه."},{"n":110,"p":24,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"يج وز للأب والج ّد للأب أن يطلّ ق عن المجن ون المطب ق زوجته مع مراع اة يحق لهما طلاق زوجة المجنون الأدواري وإن طال دور جنونه. مصلحته، ولا ّ"},{"n":111,"p":24,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"ليس للأب والج ّد للأب طلاق زوجة الس كران والمغمى عليه، ب لهما يطلق ان حال إفاقتهما."},{"n":112,"p":24,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"إذا طلّق الزوج ثم ادعى عدم كون الطلاق مقص وداً له فإن ص دّقته الزوجة فهو والا لم يسمع منه."},{"n":113,"p":24,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"الإكراه الذي لا يصح الطلاق معه يتحقق باجتماع أمور ثلاثة: الأول: ص دور الوعي دمن المكره -بالكس ر -عل ى ترك الطلاق بما يضر بالمكره بالفتح في نفسه أو عرضه أو ماله أو على بعض من يهمه أمره، مع حصول الخ وف له من تنفيذ ما توعد به.ومثل ه ما إذا أمره بطلاق زوجته مع حص ول الخ وف له من الح اق الض رر به لو خالفه وإن لم يصدر منه وعيد صريح. الثاني: أن يكون الض رر المتوعد به مما لا يتع ارف لمث ل المكره -بالفتح -تحمله تجنباً عن قيامه بطلاق زوجته. الثالث: أن لا يتمكن من التخلص عن الطلاق بما لا يضر بحاله من الاس تعانة بالغير ونحو ذلك."},{"n":114,"p":25,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"إذا أوق ع الطلاق مخافة إض رار الغير به لو لم يفع لمن دون وعيد منه ولا أمر منه به لم يضر بصحته، كما لو تزوج امرأة ثم رأى أنه لو لم يطلقها لأضر به بعض أقربائها. ّ ق، فلو وجب عليه أن يطلق"},{"n":115,"p":25,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"لا يضر الاكراه على الطلاق بصحته إذا كان عن ح ّ زوجته لعدم تمكنه من الانفاق عليها وعدم صبرها على ذلك فامتنع فأكره عليه فطلّق ص ّح الطلاق. شروط المطل َّقة"},{"n":116,"p":25,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"يشترط في الُمطل َّقة: أولاً: أن تكون ط اهرة من الح يض والنف اس وإن لم تغتس لمن ح دثهما، فيبط لطلاق الح ائض والنفس اء وإن لم يعلم المطلق بذلك، ويس تثنى من ذلك ما يأتي: أ.أن تكون غير مدخول بها، أي لم يجامعها زوجها. سر للزوج اس تعلام حاله امن حيث الح يض والطهر لغيبة ب.أن لا يتي ّ أو خ وف أو لتكتمها عنه حالها أو لغير ذلك، بش رط أن تمضي على ذلك مدّة شهر. ثانياً: أن تكون في طهر لم يجامعها زوجها فيه ولو بغير إن زال.ويس تثنى من ذلك: أ.اليائس ة أي التي انقط ع عنها دم الح يض لكب رس نها، كم الوك ان بعد بلوغها الخمسين سنة هلالية. ب.الحامل المستبين حملها. ج.المس ترابة -أي التي لا تح يض وهي في سّن من تح يض، -فإن ه إذا أراد تطليقها اعتزلها ثلاثة أشهر ثم طلقها فيص ح طلاقها حينئ ٍذ وإن كان في طهر الجماع."},{"n":117,"p":26,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"إذا انفصل الزوج عن زوجته في طهر جامعها فيه لم يجز له طلاقها مع علمه بعدم انتقالها من ذلك الطهر الى طهر آخر، وأم ا مع الش كفي ذلك فيج وز له طلاقها بشرط عدم تمكنه من اس تعلام حالها ومضي مدة ش هر على انفصاله عنها."},{"n":118,"p":26,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"إذا أخب رت الزوجة أنها ط اهرة فطلقها الزوج أو وكيله ثم ادعت أنها كانت حائضاً وقت الطلاق لم تقبل دعواها بغير دلي ل، ويؤخ ذ بخبرها الأول ما لم يثبت خلافه. شروط الطلاق"},{"n":119,"p":26,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"يشترط في ص ّحة الطلاق: ت طا ِلق) أو (فلانة طا ِلق) أو ٰ (هذه طا ِلق) صة وهي قوله(: أ ْن ِ أولاً: الصيغة الخا ّ وما أشبه ذلك من الألفاظ الدالّة على تعيين المطلّقة والمش تملة على لفظة قتك) (طا ِلق)، فلا يقع الطلاق بقوله(: فلانة مطلّقة) أو (طلّقت فلانة) أو (طلّ ِ ونحو ذلك. تقبلي معل وم الحصول أو متوقّ ع ثانياً: التنجيز، فلو علّق الطلاق على أمر مس ّ حالي محتمل الحصول بطل. الحصول، أو أمر ّ ثالثاً: الإش هاد، بمعن ى إيق اع الطلاق بحض ور رجل ين عدلين يس معان إنش اء الطلاق، سواء قال لهما: اشهدا أو لم يقل."},{"n":120,"p":26,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"لا يقع الطلاق بما يرادف الصيغة الم ذكورة من سائر اللغ ات مع الق درة على سر التوكيل أيضاً فيج زئ إيقاعه بتلك الص يغة، وأم ا مع العجز عنه وعدم تي ّ إيقاعها بما يرادفها بأية لغة كانت."},{"n":121,"p":27,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"لا يقع الطلاق بالإشارة ولا بالكتابة مع القدرة على النطق، وأ ّما مع العجز عنه كما في الأخ رس فيص ّح منه إيقاعه بالكتابة وبالإش ارة المفهمة على نحو ما يبرز سائر مقاصده."},{"n":122,"p":27,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"يش ترط اجتم اع الش اهدين وحض ورهما مجل سانش اء الطلاق، ف لا يكفي ان، أن يس معه أحدهما في مجل سويك رر فيس معه الآخر في مجل سث ٍ كما لا يكفي سماعهما ص وت المطلق ومش اهدة ص ورته عن طري ق وس ائل الاتصال الحديثة."},{"n":123,"p":27,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"لا يعتبر في الشاهدين معرفة المرأة المطلقة بعينها، فل وق الالزوج (زوجت ي فلانة ط الق) بمس مع الش اهدين كفى وإن لم يعرفا أن فلانة من هي بل وإن اعتقدا أنها غيرها. ع دل آخر في الش اهدين،"},{"n":124,"p":27,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"إذا طلّق الوكي لعن الزوج لا يكتفى به مع َ كما أنّه لا يكتفى بالموكّل مع عَدل آخر."},{"n":125,"p":27,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"العَدل: هو من كان ملتزماً في سلوكه العملي بالأحك ام الإلزامية في الش ريعة الإسلامية، لا يتعمد ترك واجب أو فعل حرام منها، ويكفي في الكش فعن ذلك ي. حسن الظاهر، أي حسن المعاشرة والسلوك الدين ّ"},{"n":126,"p":27,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"لا يعتبر في ص ّحة الطلاق علم الزوجة به، ولا تجب موافقتها عليه الا فيما تقدم في المادة (.)٩"},{"n":127,"p":27,"c":"الباب الثاني - الطلاق › الفصل الأول - شروط المط ِلّق والمطل َّقة والطلاق","t":"إذا اختلف الزوجان بعد إيقاع الطلاق في ص حته -ك أن ادعى الزوج أنه كان مكره اً أو أن الش اهدين لم يكون اع ادلين أو ادعت الزوجة أنها كانت حائض اً أو أنها كانت في طهر واقعها فيه زوجها -ف القول ق ولم دعي الص حة بيمينه الا أن يقيم مدعي البطلان البينة على مدعاه.وإذا تصادق الزوجان على بطلان الطلاق لفقد بعض ش روطه يحكم لهما بذلك مع احتمال الصدق وكون الحق لا يعدوهما."},{"n":128,"p":28,"c":"الباب الثاني - الطلاق › الفصل الثاني - أقسام الطلاق وبعض أحكامه","t":"الط لاق غير الج امع للش روط المتقدمة باط لش رعاً، وتبق ى المرأة معه في عصمة الزوج تثبت لها جميع أحكام الزوجة."},{"n":129,"p":28,"c":"الباب الثاني - الطلاق › الفصل الثاني - أقسام الطلاق وبعض أحكامه","t":"طلاق الثلاث على نحوين: الأول: أن يكون مرس لاً بأن يق ول الزوج(: فلان ة ط الق ثلاث اً) وه ذا يقع باطلاً إذا أريد به ما هو ظاهره من ايقاع ثلاث طلقات. الثاني: أن يكون ولاًء، ب أن يك رر الزوج ص يغة الطلاق ثلاثم رات كأن يق ول: (ه ي ط الق، ه ي ط الق، ه ي ط الق) من دون تخل لرجعة في الب ين قاص داً تعدد الطلاق، وهذا يقع طلاقاً واحداً فقط."},{"n":130,"p":28,"c":"الباب الثاني - الطلاق › الفصل الثاني - أقسام الطلاق وبعض أحكامه","t":"الطلاق الصحيح قسمان: الأول: الب ائن، وه وال ذي تخرج به المطلقة عن عص مة الزوج، ف لا يش رع له الرجوع بها.ومن أقسامه: أ.طلاق اليائسة. ب.الطلاق قبل الدخول. ج.الطلاق الذي سبقه طلاقان إذا وقع بينهما رجوعان -أو ما بحكمهما - من المطلق. د.طلاق الخلع والمباراة مع عدم رجوع الزوجة فيما بذلت. ه.الطلاق الذي يوقعه القاضي بطلب الزوجة عند امتناع الزوج عن أداء حقوقها الشرعية وفقاً لأحكام المواد (.)٦٧، ٦٦، ٦٥ الثاني: الرجع ي، وه وال ذي تبقى فيه المطلقة في عص مة الزوج فيش رع له الرجوع بها ما دامت في العدة."},{"n":131,"p":29,"c":"الباب الثاني - الطلاق › الفصل الثاني - أقسام الطلاق وبعض أحكامه","t":"الرجع ة هي رجوع الزوج عما أوقعه من الطلاق في أثناء العدة فيمن ع من تأثيره في تحقق الفرقة بانقضائها، ف لا رجعة في البائنة ولا في الرجعيّة بعد انقضاء عدّتها."},{"n":132,"p":29,"c":"الباب الثاني - الطلاق › الفصل الثاني - أقسام الطلاق وبعض أحكامه","t":"تتحقّق الرجعة بأحد أمرين: (ر َج ْعت ُ ِك) الأول: أن يتكلّم بكلام دا ّل على إنش اء الرجوع كقول ه(: را َج ْعت ُ ِك) أو َ (ارتج ْعت ُ ِك) ونحو ذلك، ولا يعتبر فيه العربيّة، بل يقع بك ّل لغ ٍة إذا كان أو َ بلفظ يفيد المعنى المقصود في تلك اللغة. الثاني: أن يأتي بفعل يقصد به الرجوع إليها، فلا تتحقّق بالفعل الخالي عن قصد الرجوع، إلا في الجماع، فإنه يكون رجوعاً وإن لم يقصد به الرجوع."},{"n":133,"p":29,"c":"الباب الثاني - الطلاق › الفصل الثاني - أقسام الطلاق وبعض أحكامه","t":"لا يشترط في الرجوع المباشرة، بل يمكن التوكيل فيه. ع اء الزوج وإخب اره به إذا كان في أثناء الع دة،"},{"n":134,"p":29,"c":"الباب الثاني - الطلاق › الفصل الثاني - أقسام الطلاق وبعض أحكامه","t":"يثب ت الرجوع بمجرد اد ّ ع اه بعد انقضائها ولم تص دقه الزوجة لم تقبل دعواه إلا بالبين ة. ولو إد ّ ولو تصادقا بعد العدّة على الرجوع قبل انقضائها يحكم لهما بذلك مع احتمال الصدق وكون الحق لا يعدوهما."},{"n":135,"p":29,"c":"الباب الثاني - الطلاق › الفصل الثاني - أقسام الطلاق وبعض أحكامه","t":"يصح الطلاق بعد الطلاق إذا تخل لبينهما الرجوع، وإن وقعا في طهر واحد من دون جم اع.فيص ح طلاق المرأة ثلاثاً بينها رجوع ان من دون جم اع في طهر واحد، ويكون الثالث بائناً لا رجوع معه في العدة."},{"n":136,"p":29,"c":"الباب الثاني - الطلاق › الفصل الثاني - أقسام الطلاق وبعض أحكامه","t":"إذا طلق الرجل زوجته ثلاثاً حرمت عليه في الثالثة حتىت نكح زوجاً غي ره، سواء كان رجوعه اليها المتخلل بين الطلقات الثلاث رجوعاً من طلاق رجعي أم زواجاً بعقد جديد بعد الخروج من العدة أو بعد طلاق بائن."},{"n":137,"p":29,"c":"الباب الثاني - الطلاق › الفصل الثاني - أقسام الطلاق وبعض أحكامه","t":"يش ترط في الزوج المح ِلّ لبعد ثلاث تطليق ات: أن يدخل بها في القُب ل، فإذا فارقها بعدئ ٍذ بموت أو طلاق وانقضت عدتها -إن لزمته العدة -ج از للزوج الأول أن يتزوجها مرة أخرى."},{"n":138,"p":30,"c":"الباب الثاني - الطلاق › الفصل الثاني - أقسام الطلاق وبعض أحكامه","t":"المح ِلّ لالم ذكور كما يوجب سقوط حكم التطليق ات الثلاث ويرف ع التح ريم الحاصل بها يرفع حكم التطليقة الواحدة والتطليقت ين أيض اً، فم ن طلق امرأته تطليقة واحدة أو تطليقت ين وانقضت عدتها ثم تزوجت غيره بالنحو المتقدم وُ طلّقت، ثم تزوجها الاول لم تحرم عليه حتى يطلقها ثلاثاً بعد زواجه منه ا، ولا تحرم بطلاقها مرة أو مرتين."},{"n":139,"p":30,"c":"الباب الثاني - الطلاق › الفصل الثاني - أقسام الطلاق وبعض أحكامه","t":"إذا طلقها ثلاثاً ومضى على ذلك مدة فادعت أنها تزوجت وفارقها زوجها الثاني ومضت العدة فإن احتمل الزوج الأول صدقها فيما ادعت جاز له أن يعقد عليها بعقد جديد. ّي ثلاث مرات."},{"n":140,"p":30,"c":"الباب الثاني - الطلاق › الفصل الثاني - أقسام الطلاق وبعض أحكامه","t":"الطلاق التسع يوجب الحرمة الأبديّة إذا وقع الطلاق العد ّ"},{"n":141,"p":30,"c":"الباب الثاني - الطلاق › الفصل الثاني - أقسام الطلاق وبعض أحكامه","t":"الطلاق العدّي مركب من ثلاث طلقات، ويشترط فيه أمران: اولاً: تخلّ لرجعت ين فلا يكفي وق وع عق دين مس تأنفين ولا وق وع رجعة وعقد مستأنف في البين. ثانياً: وقوع الجماع بعد كّل رجعة. ِ العدَد جمع (ِعد َّة) وهي مدة انتظ ار المرأة بعد مفارقة زوجها، أو بعد جم اع"},{"n":142,"p":30,"c":"الباب الثاني - الطلاق › الفصل الثالث - العدَد","t":"غير الزوج لها لش به ٍة.والمقص ود بالانتظ اره وأنها إذا كانت خليّة لم يجز لرجل آخر الزواج منها خلال تلك المدة، وإذا كانت ذات زوج لم يجز لزوجها أن يجامعها في تلك المدة. الفرع الأول عدّة الطلاق"},{"n":143,"p":30,"c":"الباب الثاني - الطلاق › الفصل الثالث - العدَد","t":"إذا طلّقت المرأة من زوجها وجب عليها الاعتداد مدّة معيّنة لا يجوز لها الزواج من غيره قبل انقضائها، وتستثنى من ذلك: اولاً: من لم يدخل بها زوجها. ثانياً: اليائسة، وإن كانت مدخولاً بها."},{"n":144,"p":31,"c":"الباب الثاني - الطلاق › الفصل الثالث - العدَد","t":"المطلّقة التي تجب عليها العدّة على أقسام: القسم الأول: المطل َّقة غير الحام لالتي يكون الطهر الفاص لبين حيض تين منها أق ّل من ثلاثة أشهر، وعدّتها ثلاثة أطهار. القسم الثاني: المطلّق ة غير الحام لالتي يكون الطهر الفاص لبين حيض تين منها ثلاثة أشهر أو أزيد، وعدّتها ثلاثة أشهر. القسم الثالث: المطلّق ة غير الحام لالتي تكون مس ترابة أي التي لا تح يض وهي في سن من تحيض وعدّتها ثلاثة أشهر أيضاً. القسم الرابع: المطلّقة الحامل، وعدّتها مدّة حملها، وتنقض يب أن تض ع حملها ولو بعد الطلاق بساعة."},{"n":145,"p":31,"c":"الباب الثاني - الطلاق › الفصل الثالث - العدَد","t":"الطهر الأول هو ما يكون بين الطلاق والحيضة الأولى وإن كان لزمن قص ير ج داً، والطه ر الثاني يكون ما بين الحيضة الأولى والثانية، والطه ر الثالث يكون ما بين الحيضة الثانية والثالثة، فإذا رأت الدم من الثالثة لحظة من أولها تنقضي العدة."},{"n":146,"p":31,"c":"الباب الثاني - الطلاق › الفصل الثالث - العدَد","t":"مبدأ عدّة الطلاق من حين وقوعه، حاض راً كان الزوج أو غائب اً، بل غ الزوجة الخبر أم لا. الفرع الثاني عدّة الفسخ والانفساخ"},{"n":147,"p":31,"c":"الباب الثاني - الطلاق › الفصل الثالث - العدَد","t":"إذا فسخ الزوج أو الزوجة عقد النكاح لعيب أو نحوه، أو انفس خ العقد بينهما لرض اع أو غيره تثبت عدة الطلاق على التفص يل المتقدم من الأطه ار أو الشهور أو وضع الحمل."},{"n":148,"p":31,"c":"الباب الثاني - الطلاق › الفصل الثالث - العدَد","t":"يستثنى من ذلك إذا حصل الانفساخ بخروج الزوج عن دين الإسلام عن فطرة، فإنه يجب على زوجته عدة الوفاة."},{"n":149,"p":31,"c":"الباب الثاني - الطلاق › الفصل الثالث - العدَد","t":"مبدأ عدة الفسخ والانفساخ من حين حصولهما، كما تقدم في عدة الطلاق. الفرع الثالث عدّة الوفاة"},{"n":150,"p":32,"c":"الباب الثاني - الطلاق › الفصل الثالث - العدَد","t":"إذا توفّي الزوج وجب على زوجته الاعتداد، وعدتها إن كانت غير حامل أربعة أشهر هلالية وعش رة أيّ ام، وإن كانت حاملاً تكون ع دّتها أبعد الأجل ين من هذه المدّة ووضع الحمل."},{"n":151,"p":32,"c":"الباب الثاني - الطلاق › الفصل الثالث - العدَد","t":"مب دأ عدّة الوفاة من حين بل وغ خبر وقوعها الى الزوجة، ف إذا كان الزوج غائب اً -م ثلاً -ول م يبلغ زوجته خبر وفاته إلا بعد مدة تعت دمن حين بل وغ الخبر إليها."},{"n":152,"p":32,"c":"الباب الثاني - الطلاق › الفصل الرابع - أحكام المفقود زوجها","t":"اولاً: المفق ود المنقطع خبره عن أهله إذا كانت زوجته تعلم بحياته أي بلد هو، حكمه ا هو لزوم الص بر والانتظ ار ولكنّه الا تعلم في ّ إلى أن يرجع إليها زوجها أو يأتيها خبر موته أو طلاقه. ويستثنى من ذلك ما إذا ثبت للقاضي انه قد هجرها تارك اً أداء ما لها من الحقوق الزوجية وقد تعمد إخفاء موضعه لكي لا يتسنى للقاضي -فيما إذا رفعت الزوجة أمرها اليه -أن يتصل به ويخيّ ره بين أمرين: إم ا أداء حقوقها أو طلاقها، فإن ه يجوز للقاضي أن يطلقها استجابة لطلبها وفقاً لما نصت عليه المادتين (٧٠و.)٧١ ثانياً: المفقود المنقطع خبره عن أهله إذا كانت زوجته لا تعلم بحياته ولا موت ه، ولي الزوج يقوم بالإنفاق عليها وكان للزوج مال ينفق منه عليها، أو كان ّ من مال نفسه، يجب عليها الصبر والانتظار الى أن يرجع زوجها أو تثبت وفاته، ولا سبيل الى طلاقها منه. ثالثاً: المفقود المنقطع خبره عن أهله إذا كانت زوجته لا تعلم بحياته ولا موت ه، ولم يكن للزوج مال يتيسر الانفاق منه على زوجته، ولا ينفق عليها وليّه إن وجد من مال نفسه، يجوز لها وإن وجد من ينفق عليها غير ي أن ترفع أمرها إلى القاضي طالبةً للطلاق عند مضي أربع سنوات الول ّ ي أمره القاضي على فقد الزوج مع الفحص عنه خلالها.فإن كان للزوج ول ّ بطلاقها وإن لم يكن أو امتنع عن الطلاق طلّقها القاضي بنفسه، فينش ئ الطلاق بصيغته الشرعية بقوله(: فلانة زوجة فلان طالق). رابعاً: يشترط موافقة المرجع الديني على طلاق زوجة المفقود وفقاً لما ورد في البند (ثالثا) من هذه المادة. خامساً: إذا تبين حياة الزوج المفقود بعد الفحص وانقضاء المدة واجراء الطلاق فإن كان ذلك في أثناء العدة فله الرجوع الى زوجته، وإن كان بعد انقضائها فلا سبيل له عليها. سادساً: إذا طلّق القاضي زوجة المفقود وفق ما تقدم ثم تب ين عدم اكتم ال الفحص على الوجه اللازم يحكم ببطلان الطلاق وعدم ترتب الأثر عليه. مفوض إليه ي -هنا -هو أبو المفقود وجدّه لأبيه، وإذا كان للمفقود وكيل ّ"},{"n":153,"p":33,"c":"الباب الثاني - الطلاق › الفصل الرابع - أحكام المفقود زوجها","t":"الول ّ ي من جهة الطلاق، بمعن ى أنه مع عدم الانفاق طلاق زوجته كان بحكم الول ّ عليها يأمره القاضي بطلاقها فإن امتنع طلقها القاضي كما تقدم. الفرع الاول طلاق الخلع"},{"n":154,"p":33,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"الخل ع هو الطلاق بفدية من الزوجة الكارهة لزوجها، وإذا كانت الكراهة من الطرفين كان مباراةً."},{"n":155,"p":33,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"الخل ع والمباراة نوع ان من الطلاق فإذا انض ّم إلى أحدهما تطليقت ان حرمت المطل َّقة على المط ِلّق حتّى تنكح زوجاً غيره."},{"n":156,"p":33,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"يش ترط في الخلع جميع ما تقدّم اعتباره في الطلاق من الص يغة الخاصة والتنجيز والإشهاد. ق عَل ٰى كذا) وقول هَ: (خلَ ْعت ُ ِك عَل ٰى كذا)"},{"n":157,"p":34,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"م نص يغ الخلع، قول ه(: أ ْن ِ ت طا ِل ٌ أو (خالَ ْعت ُ ِك عَل ٰى كذا) وقوله (فلان ة ُم ْختَ ِلعَ ةٌ عَل ٰى كذا) بكسر لام مختلع ة. ويذكر مكان (كذا) الفداء الآتي ذكره."},{"n":158,"p":34,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"يشترط في الزوج الخالع جميع ما تقدّم اعتباره في المط ِلّق من العق لوالقصد والاختيار."},{"n":159,"p":34,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"يشترط في الزوجة المختلعة جميع ما تقدّم اعتباره في المطل َّقة، ويضاف إليها: أولاً: أن تكون كارهة لزوجها، ويعتبر بلوغ كراهتها له ح ّداً يحملها على تهديده بترك رعاية حقوقه الزوجية في حال بقائها في عصمته. ثانياً: أن تبذل الفداء لزوجها عوضاً عن الطلاق."},{"n":160,"p":34,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"الكراهة المعتبرة في الخلع أع ّم من أن تكون ناش ئة من خصوص يّات الزوج كس وء خلقه ونحو ذلك، وم ن أن تكون من جهة عدم إيفائه بعض الحقوق التزوج عليها بأُخرى وإن سمح المستحبّة للزوجة أو قيامه بما لا ترتض يه ك ّ به القانون."},{"n":161,"p":34,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"إذا طلقها بعوض مع عدم كراهتها له بالحد المتقدم لم يصح الخلع ولم يملك العوض بل يبطل أصل الطلاق أيضاً. وإذا صالحته على مال واشترطت عليه أن يطلقها صح الطلاق ولا يكون بائناً بل رجعياً وفق ما تقدم، ول واشترطت عليه في عقد الص لح عدم الرجوع في العدة صح الشرط ول زم الزوج الوفاء به ولكن لو خ الف ورجع يصح الرجوع ويثبت للزوجة الخيار في فسخ الصلح من جهة التخلف عن الشرط."},{"n":162,"p":34,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"يشترط في الفداء: أولاً: أن يكون بذله باختيار الزوجة، فلا يص ّح مع إكراهها على البذل سواء أكان الإكراه من الزوج أم من غيره.وأما الاضطرار الى البذل كما إذا لم تجد طريقاً آخر للخلاص من الزوج فلا يمنع من صحة البذل. ثانياً: كونه مملوكاً للمختلعة أو ما بحكم المملوك كمبلغ في ذمتها. ثالثاً: كون هذا مالية عرف اً عين اً كان أو دين اً أو منفعة وإن زاد على المهر المسمى. رابعاً: كون ه معلوم اً بالع ّد في النق ود ونحوه امن المع دودات أو بغير ذلك على النحو المعتبر في البيع وما يماثله من المعاوضات.وإذا كان المبذول مهرها كفى العلم به بنح وما يعتبر في المهر من المعلومية، وق د تقدم في المادة (.)٤٨"},{"n":163,"p":35,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"الخل ع وإن كان قس ماً من الطلاق وهو من الإيقاع ات ّإلا أنّه يش به العق ود في الاحتي اج إلى ط رفين وإنش اءين: ب ذل شيء من طرف الزوجة ليطلّقها الزوج، وإنشاء الطلاق من طرف الزوج بما بذلت، ويقع ذلك بأحد نحوين: الأول: أن يقدّم البذل من طرفها على أن يطلّقها، فيطلّقها على ما بذلت. مصرحاً بذكر العوض فتقبل الزوجة بعده. الثاني: أن يبتدئ الزوج بالطلاق ّ"},{"n":164,"p":35,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"يعتبر في ص ّحة الخلع الموالاة بين إنشاء البذل والطلاق، بمعنى تعق ُّ بأح دهما بالآخر قبل انصراف صاحبه عنه."},{"n":165,"p":35,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"يجوز أن يكون البذل والطلاق في الخلع بمباشرة الزوجين أو بتوكيلهما الغير أو بالاختلاف.كم ا يجوز التوكيل في سائر ما يتعل قبه من تعي ين الفداء وتسليمه وتسلمه وغير ذلك."},{"n":166,"p":35,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"إذا وقع الخلع بمباش رة الزوجين فإ ّما أن تب دأ الزوجة وتق ول: (َب َذ ْلتُ لَ كَ ما َ ي ِلت ُ َط ِلّقَن ي) فيق ول علَ ْي كَ ِم نَ الم ْهر أو الش ِ يء الكذائ ّ ق أو ُم ْختَ ِلع ةٌ بكسر اللام -عَل ٰى ما بَ َذ ْلتِ)، وإ ّما أن الزوج(: أ ْن ِ ت طا ِل ٌ يبتدئ الزوج -بع دما اتفقا على الطلاق بع وض -فيق ول: (رضيتُ). (أ ْن ِ ت طا ِل ٌ ق أو ُم ْختَ ِلعةٌ على كذا) فتقول الزوجة(: قَبِ ْلتُ) أو َ"},{"n":167,"p":35,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"إن وقع البذل والطلاق من وكيلين يق ول وكيل الزوجة مخاطباً وكيل الزوج: ي ِليَ ْخلَعَه ا) (ع َْن ُم َو ِ ّكلَتي فلانة بَ َذ ْلتُ لُم َو ِ ّك ِلكَ ما َ علَ ْي ِه ِم َن المه ِْر أو المبلغ الكذائ ّ فيقول وكيل الزوجَ: ع ْن ُم َو ِ ّك ِلي َلى ما بَ َذلَتْ) أو يقولَ (: (ز ْو َجةُ ُم َو ِ ّك ِلي طا ِل ٌ قع ٰ َلى ما َب َذلَتْ). َخلَ ْعتُ ُم َو ِ ّكلَتَكَ ع ٰ"},{"n":168,"p":36,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"إن وقع البذل والطلاق من وكيل أحدهما مع الآخر، كوكي لالزوجة مع الزوج يقول وكيلها مخاطباً الزوج(: ع َْن ُم َو ِ ّكلَتي فلانة بَ َذ ْلتُ لَ كَ ما َ علَ ْي كَ ِم نَ الم ْه ِر ي عَل ٰى ْ ي ط الِقٌ عَل ٰى ما بَ َذ َلتْ) أنت ُ َط ِلّقَه ا) فيق ول الزوجِ (: ه َ أو الشيء الكذائ ّ َلى كذا) فيق ول وكيله ا: أو يبتدئ الزوج مخاطباً وكيلهاُ (: م َو ِ ّكلَت ُكَ فلانة طا ِل ٌ قع ٰ (ع َْن ُم َو ِ ّكلَتي قَ ِب ْلتُ ٰذ ِلك)."},{"n":169,"p":36,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"طلاق الخلع بائن لا يقع فيه الرجوع ما لم ترجع المرأة أثناء العدة فيما بذلت. فإذا رجعت بالمبذول أصبح الطلاق رجعياً، وجاز للمطلق الرجوع."},{"n":170,"p":36,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"يشترط في جواز رجوعها في المبذول إمكان رجوع الزوج اليها، فل ولم يجز له الرجوع لم يكن أثر لرجوعها كما في الموارد الآتية: اولاً: إذا كان الخلع طلاقاً بائناً في نفسه ككونه طلاقاً ثالثاً. ثانياً: إذا كانت الزوجةم ّمن لا عدّة لها كاليائسة وغير المدخول بها. تزوج الزوج بأُختها أو برابعة. ثالثاً: إذا ّ رابعاً: لو لم يعلم الزوج برجوعها في الفدية حتّى انقضت العدة. الفرع الثاني طلاق المباراة"},{"n":171,"p":36,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"المب اراة كالخلع في جميع ما تقدّم من الش روط والأحك ام، وتختل فعنه في أُمور ثلاثة: الأول: إنّها تترتّب على كراهة كّل من الزوجين للآخر. الثاني: يشترط فيها أن لا يكون الفداء أكثر من مهرها. الثالث: إذا أوق ع إنش اءها بلف ظ (ب ارأتُ) يل زم أن يتبعه بص يغة الط لاق، فلا يجت زئ بقول ه(: ب ارأت زوجتي على كذا) حتّى يتبعه بقوله ت طالق) أو (فهي طالق). (فأن ِ"},{"n":172,"p":36,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"يج وز في المباراة -ك الخلع -إيقاعه ا بلف ظ الطلاق مج ّرداً بأن يق ول َلى ما بَذَ ْلتِ). الزوج -: بعد ما بذلتْ له شيئاً ليُ َط ِلّقَها (-أ ْن ِ ت طا ِل ٌ قع ٰ"},{"n":173,"p":37,"c":"الباب الثاني - الطلاق › الفصل الخامس - طلاق الخلع والمباراة","t":"طلاق المباراة بائن كالخلع لا يجوز الرجوع فيه للزوج ما لم ترجع الزوجة في الفدية قبل انتهاء العدّة، فإذا رجعت فيها في العدّة جاز له الرجوع إليها على نحو ما تقدّم في الخلع."},{"n":174,"p":37,"c":"الباب الثالث - الوصية","t":"الوصية: عهد الإنسان بما يريده بعد وفاته.وهي نوعان: ق لغي ره الأول: التمليكيّة: وهي أن يجعل الشخص شيئاًم ّم اله من مال أو ح ّ بعد وفاته.ولا يشترط فيها القبول إن كانت تمليكاً لعن وان عا ّم كالفقراء، وإن كانت تمليكاً للشخص اُشترط فيها قبول الموصى له. الثاني: العهديّة: وهي أن يَ ْع َهد الشخص بت ولّي أحد بعد وفاته أم راً يتعلّ قبه أو بغيره، ولا تحتاج إلى القبول."},{"n":175,"p":37,"c":"الباب الثالث - الوصية","t":"الوص يّة التمليكيّة لها أرك ان ثلاثة: الموص ي، والموص ى به، والموص ى له، وأ ّما الوص يّة العهديّة فيكون قوامه اب أمرين: الموص ي، والموص ى به، ولكن إذا ع يّن الموصي شخصاً لتنفي ذها كانت أطرافها ثلاثة بإض افة ي)، وإذا كان الموصى به (الموص ى إلي ه) وهو الذي يطلق عليه (الوص ّ أمراً متعلّقاً بالغير كتمليك مال له كانت أطرافها أربعة بإضافة الموصى له."},{"n":176,"p":37,"c":"الباب الثالث - الوصية","t":"تتحقق الوصية بكل ماد ّل عليها من لفظ ص ريح أو ظ اهر أو فعل وإن كان كتابة أو إشارة، ويكفي وجود مكتوب بخطه أو بتوقيعه بحيث يظهر من ق رائن الأح وال إرادة العمل به بعد موته.وأم ا إخب اره عن الرغبة في تنفيذ بعض الأمور بعد وفاته فلا تتحقق به الوصية وإن كان يحسن بالورثة تحقي ق رغبته براً به. مهما أمكنهم ذلك ّ"},{"n":177,"p":37,"c":"الباب الثالث - الوصية","t":"رد الموصى له الوصية في الوصية التمليكية مبطل لها إذا كان الر ّد بعد موت الموصي ولم يسبق بقبوله.وأما إذا سبقه القبول بعد الموت أو في حال حياته فلا أثر للرد، وكذلك لا أثر للرد في حال الحياة."},{"n":178,"p":38,"c":"الباب الثالث - الوصية","t":"إذا أوصى له بشيئين فقبل أحدهما ورد الآخر صحت فيما قبل وبطلت فيما ردّ، وكذا لو أوصى له بش يء واحد فقب لفي بعضه ورد في البعض الآخ ر، الا إذا علم من حال الموصي ارادة تمليك المجموع من حيث المجموع."},{"n":179,"p":38,"c":"الباب الثالث - الوصية","t":"لا يجوز للورثة التصرف في العين الموصى بها قبل أن يختار الموصى له أحد الأمرين من الرد والقبول.ول يس لهم إجب اره على الاختي ار مع ّج لاً ّإلا إذا كان تأخيره موجباً للضرر عليهم فيجبره القاضي حينئ ٍذ على اختيار أحدهما."},{"n":180,"p":38,"c":"الباب الثالث - الوصية","t":"إذا مات الموصى له قبل قبوله ورده قام وارثه حين وفاته مقامه في ذلك، فل ه القبول أو الرد إذا لم يرجع الموصي من وصيته، ولا فرق بين أن يم وت في حياة الموصي أو بعد وفاته."},{"n":181,"p":38,"c":"الباب الثالث - الوصية","t":"يجوز للموصي أن يرجع عن وصيته، وتبديلها من أصلها أو من بعض جهاتها وكيفياتها ومتعلقاتها.ويستثنى من ذلك ما إذا كانت الوصية شرطاً في عقد لازم فإنه لا يصح الرجوع عنها الا بموافقة المشروط له."},{"n":182,"p":38,"c":"الباب الثالث - الوصية","t":"يتحقق الرجوع عن الوصية بالقول أو بالفعل، مثل أن يوصي بص رف ثلثهث ُ َّم يوصي بوقفه ملتفتاً الى وصيته الأولى، ومثل أن يوصي بوقف عين أو بصرفها ث ُ َّم يبيعها أو يهبها مثلاً، وك ذا إذا أوك لغيره في بيعها مثلاً مع التفاته إلى وصيّته."},{"n":183,"p":38,"c":"الباب الثالث - الوصية","t":"لا يشترط في وجوب العمل بالوصيّة عدم مرور مدّة طويلة عليها، فإذا أوصى ث ُ َّم مات ولو بعد مرور سنين وجب العمل بوصيّته، ولك ن يشترط عدم الرجوع عنها، وإذا شكّ في الرجوع بنى على عدمه، هذا فيما إذا كانت الوص يّة مطلقة أي بأن كان مقصود الموصي وقوع مضمون الوصيّة والعمل بها بعد موته في ّ زمان توفّاه الله تعالی، أما إذا كانت مقيّدة بموته في سفر معين أو عنم رض معين مثلاً ولم يتّفق موته في ذلك السفر أو عن ذلك المرض بطلت تلك الوصيّة واحتاج إلى وصيّة جديدة. شروط الموصي"},{"n":184,"p":39,"c":"الباب الثالث - الوصية","t":"يشترط في الموصي: أولاً: البلوغ، فلا تصح وصية الص بي إلا إذا بل غ عشر سنوات وكانت وصيته في وجوه الخير أو لأقربائه. ثانياً: العقل، فلا تصح وصية المجن ون والمغمى عليه والس كران حال جنونه وإغمائه وسكره. ثالثاً: الرش د.ف لا تص ّح وصيّة الس فيه في أمواله وتص ّح في غيرها كتجهيز جنازته. رابعاً: الاختيار.فلا تص ّح وصيّة المكره عليها. خامساً: ان لا يكون قاتل نفسه، ف إذا أوصى الشخص بعد ما أح دث في نفسه ما يوجب موته لم تصح وصيته إذا كانت في ماله، أم ا إذا كانت في غيره من تجهيز جنازته ونحوه ص حت، وك ذا تصح الوصية إذا فعل ذلك لا عن عمد بل كان خطأ أو سهوا أو كان لا بقصد الموت بل لغ رض آخر أو على غير وجه العص يان مثل الجه اد في سبيل ّ.وإذا أوصى قبل أن يح دث في نفسه ما يوجب الموت ثم أح دث فيها ص حت وصيته وإن كان حين الوصية بانياً على أن يحدث ما يوجب الموت بعدها. شروط الموصى به"},{"n":185,"p":39,"c":"الباب الثالث - الوصية","t":"يش ترط في الوص يّة العهديّة أن يكون ما أوصى به عم لاً سائغاً، وأن لا يع ّد سفهاً وعبثاً من الموصي."},{"n":186,"p":39,"c":"الباب الثالث - الوصية","t":"يش ترط في الوص يّة التمليكيّة أن يكون الموصى بهم الاً أو حقّ اً ق ابلاً للنق ل كحقّي التحجير والاختصاص، من غير فرق في المال بين كونه عين اً أو دين اً فيذ ّمة الغير أو منفعة.ويش ترط إذا كان عين اً أن تكون موج ودة فع لاً أوم ّما سيوجد، وتك ون لها منفعة محلّلة معت ّد بها.ويش ترط إذا كان منفعة أن تكون محلّلة مقصودة للعقلاء."},{"n":187,"p":40,"c":"الباب الثالث - الوصية","t":"يشترط في الموصى به -في الوصيّة التمليكيّة وكذلك في العهديّة بغير الديون ونحوه امن الحقوق الماليّة -أن لا يكون زائ داً على الثلث، ف إذا أوصى بما زاد عليه بطل الإيصاء في الزائد ّإلا مع إجازة الوارث. وإذا أجاز ما زاد عن الثلث بعض الورثة دون بعض نفذ في حصة المجيز دون الآخر، وإذا أجازوا في بعض الموصى به وردوا في غيره صح فيما أج ازوه وبطل في غيره."},{"n":188,"p":40,"c":"الباب الثالث - الوصية","t":"تنف ذ إجازة الوارث سواء كانت في حال حياة الموصي أو بعد وفات ه، وليس له بعد الإجازة الرجوع عنها في الحالتين.ولا أثر لر ّد الوارث في حال حياة الموصي إذا لحقته الإج ازة بعد وفاته، وأ ّما إذار ّد بعد وفاته فلا أثر للإجازة بعده."},{"n":189,"p":40,"c":"الباب الثالث - الوصية","t":"يش ترط في إجازة الوارث الوصية الزائ دة على الثلث إمض اء الوصية بمعنى انشاء القبول بها ولا يكفي فيها مجرد الرضا القلبي بها."},{"n":190,"p":40,"c":"الباب الثالث - الوصية","t":"إذا أوصى بعين وأوصى بالثلث فيما ع داها أيضاً نف ذت الوص يّة في ثلثها وتوقّفت في ثلثيها على إجازة الورثة."},{"n":191,"p":40,"c":"الباب الثالث - الوصية","t":"إذا أوصى بعين ولم يوص بالثلث فإن لم تكن الوصيّة زائدة على الثلث نف ذت، وإن زادت على الثلث توقّف نفوذها في الزائد على إجازة الورثة. ي من المال كمليون دينار، يلاحظ في كونه"},{"n":192,"p":40,"c":"الباب الثالث - الوصية","t":"إذا أوصى بعين معيّنة أو بمقدار كلّ ّ بمقدار الثلث أو أق ّل أو أكثر بالإض افة إلى أم وال الموصي حين الموت لا حين الوصيّة."},{"n":193,"p":40,"c":"الباب الثالث - الوصية","t":"إذا كانت الع ين حين الوص يّة بمقدار الثلث فص ارت أكثر من الثلث حال الموت -إ ّما لزيادة قيمتها أو لنقصان قيمة غيرها أو لخروج بعض أمواله عن ملكه -نفذت الوصيّة فيما يساوي الثلث وبطلت في الزائد ّإلا إذا أجاز الورثة. مشاع كالثلث فإن كان حين الوفاة مس اوياً له حين الوص يّة بكسر"},{"n":194,"p":40,"c":"الباب الثالث - الوصية","t":"إذا أوصى ٍ ٍ تص ّح الوص ّية فيه بتمامه، وكذلك إذا كان أق ّل فتص ّح فيه بتمامه حين الوفاة. وأ ّما إذا كان حين الوفاة أكثر منه حين الوصيّة كما لو تجدّد له مال يجب إخراج ثلث الزيادة المتجدّدة أيضاً ولا يقتصر على ثلث المقدار الموجود حين الوصيّة، ّإلا أن تقوم القرينة على إرادة الوص يّة بثلث الأعي ان الموج ودة حين الوص يّة لا غير فإذا تبدّلت أعيانه الم يجب إخراج شيء، أو تقوم القرينة على إرادة الوصيّة بمقدار ثلث الموجود حينها وإن تبدّلت أعيانها فلا يجب إخراج الزائ د. وإذا كان كلامه محفوف اً بما يوجب إجم الالم راد يقتصر على الق در المت يقّن وهو الأق ّل."},{"n":195,"p":41,"c":"الباب الثالث - الوصية","t":"إذا عين الموصي الثلث في عين مخصوصة تع ين، وإذا فّوض التعي ين الى الوصي فعيّنه في عين مخصوصة تع ين أيض اً، ف إذا حصل منها نم اء بعد وفاته كان النم اء له وح ده وإن تل فبعض ها أو تمامها اخ تص التل فبه ولم يشاركه فيه بقية الورثة. وإن لم يعين الثلث كان مشاعاً في التركة، فان تلف من التركة شيء كان التلف على الجميع وإن حصل للتركة نم اء كان النم اء مش تركا بين الجمي ع. فوض الميت له ولا يتعين الثلث في عين بعينها بتعيين الوصي إذا لم يكن قد ّ ذلك إلا مع رضا الورثة.ب لّ ي إن لهم دفع قيمته من غيرها وليس للوص ّ الرفض.ويستثنى من ذلك ما إذا وجدت قرينة علی إرادة الموصي إخراج الثلث من أعيان الترکه لم يجز إخراج القيمة."},{"n":196,"p":41,"c":"الباب الثالث - الوصية","t":"إذا كان ما أوصى بهم الاً معيّن اً يس اوي الثلث أو دونه اخ تصّ به الميّت تقر ملكيّة أو الموصى له ولا اعت راض فيه للورثة كما تقدّم، ولك ن إنّما تس ّ الموصى له أو الميّت في تمام الموصى به فيما إذا كان يصل إلى الورثة ضعف استقرت ملكيّة تمام المال ما أوصى به، فإذا كان له مال بيد الورثة بهذا المقدار ّ ي أن يتص ّرف فيه بما يش اء أو بما ق ّرر له، المع يّن، فللموص ى له أو الوص ّ وأ ّما إذا لم يكن ما بأي دي الورثة من التركة يبلغ ضعف الموصى به واحتم ل-احتم الاً معت ّداً به -ع دم وص ول هذا المقدار إليهم توقّ فالتص ّرف في تمام الموصى به على إجازتهم أو وصول ضعفه إليهم، فمع انتفاء الأمرين يش اركون الموصى له أو الميّت في المال المع يّن بالنسبة، فل وكان ما ع دا الموصى به بتمامه خارجاً عن أيديهم كما إذا كان بيد غاصب مثلاً أو في ذمة مدين كان ثلث الموصى به للموصى له أو الميّت وثلثاه للورثة."},{"n":197,"p":42,"c":"الباب الثالث - الوصية","t":"يحسب من التركة ما في حكم مال الميّت بعد الموت كالدية وما يملكه بعد موته إذا أوجد سببه قبل الموت. تبرع متب ّرع في أدائه بعد وفاته"},{"n":198,"p":42,"c":"الباب الثالث - الوصية","t":"إذا كان عليه دين فأبرأه الدائن بعد وفاته أو ّ لم يكن مستثنى من التركة وكان بمنزلة عدمه."},{"n":199,"p":42,"c":"الباب الثالث - الوصية","t":"يحس بالثلث بعد اس تثناء ما يخرج من الأصل من الحقوق المالية والح ج الواجب بالاستطاعة.والحقوق المالية هي الأموال التي اشتغلت بها ذمة الميت مثل المال الذي اقترضه والمبي ع الذي باعه سلفاً وثمن ما اش تراه نس يئة وع وض المض مونات وأروش الجناي ات ونحوها ومنها الخم سوالزك اة ور ّد المظالم."},{"n":200,"p":42,"c":"الباب الثالث - الوصية","t":"إذا كانت الوص ايا كله امن الواجب ات التي لا تخرج من الأصل كالواجب ات البدنية -كالصوم والص لاة -والكف ارات والن ذور أخرجت من الثلث فإن زادت على الثلث وأج از الورثة أخرجت جميعها وإن لم يجز الورثة ورد النقص على جميع الوصايا بالنسبة."},{"n":201,"p":42,"c":"الباب الثالث - الوصية","t":"إذا كانت الوص ايا المتع ددة التي أوصى بإخراجه امن الثلث مختلفة بعض ها واجب يخرج من الأصل وبعضها واجب لا يخرج من الأصل، فان وس عها الثلث أخرج الجميع وكذلك ان لم يس عها وأج از الورثة.أم ا إذا لم يس عها ولم يجز الورثة فيقسم الثلث على الجميع وما يجب إخراجه من أصل التركة يلزم تتميمه منه."},{"n":202,"p":42,"c":"الباب الثالث - الوصية","t":"إذا أوصى بوص ايا متع ددة متض ادة كان العمل على الأخي رة وتك ون مبطلة لما سبقها."},{"n":203,"p":43,"c":"الباب الثالث - الوصية","t":"إذا أوصى بثلثه لش خص ثم أوصى بنص فثلثه لآخر كان الثلث بينهما على السوية.وإذا أوصى بعين شخصية لشخص ثم أوصى بنصفها لآخر كانت الثانية مبطلة للأولى بمقدارها."},{"n":204,"p":43,"c":"الباب الثالث - الوصية","t":"لو أوصى بإخراج بعض ورثته من الميراث لم تصح الوصية بذلك من دون إجازة ذلك الوارث ولو في حال حياة الموصي.ولك ن إذا لم يكن قد أوصى بالثلث وأوصى بذلك وجب العمل بالوصيّة بالنسبة إلى الثلث بصرف سهم ذلك البعض من الثلث إلى غيره من الورثة، فإذا كان له ولدان وكانت التركة ستّة ملايين دينار فأوصى بحرمان ولده الأكبر من الميراث أعطي الأكبر ملي ونين وأعطي الآخر أربعة ملايين. الموصى له"},{"n":205,"p":43,"c":"الباب الثالث - الوصية","t":"تصح الوصية العهدية لمن يتوقع وجوده في المستقبل مثل أن يوصي بإعط اء مال لأولاد ولده الذين لم يول دوا حال الوصية ولا حين موت الموصي، فيبق ى المال الموصى به في مل كالموصي فإن ول دوا بعد ذلك أعطي لهم وإلاّ كان ميراث اً لورثة الموصي، ويس تثنى من ذلك ما إذا وجدت قرينة على انه أراد صرفه في وجوه البّر إذا لم يوجد الموصى له فإنه يصرف فيها."},{"n":206,"p":43,"c":"الباب الثالث - الوصية","t":"لا تصح الوصية التمليكية لمن لا يوجد إلى زمان موت الموصي كما إذا أوصى لمن يكون له من الأحفاد بعد وفاته."},{"n":207,"p":43,"c":"الباب الثالث - الوصية","t":"تص ّح الوصية للحمل الموجود حين الوصية، ف إن تولّد حيّ اً مل كالموصى به بقبول وليّه ّ وإلا بطلت الوصيّة ورجع المال إلى ورثة الموصي."},{"n":208,"p":43,"c":"الباب الثالث - الوصية","t":"تصح الوصية للمسلم من مذهب آخر بل تصح لغير المسلم أيض اً، كم ا إذا كان بعض أقربائه من غير المسلمين فأوصى له بمال من ثلثه."},{"n":209,"p":43,"c":"الباب الثالث - الوصية","t":"إذا أوصى لجماعة ذكورا أو إناثا أو ذكورا وإناثا بم الاش تركوا فيه على الس وية إلا أن تكون قرينة على التفض يل.وإذا أوصى لأبنائه وبناته أو لأعمامه وعماته أو أخواله وخالاته أو أعمامه وأخواله كان الحكم في الجميع التسوية إلا أن تقوم قرينة على التفضيل. الوصي"},{"n":210,"p":44,"c":"الباب الثالث - الوصية","t":"للموصي أن يعين شخصا لتنفيذ وصاياه، يسمى: الوصي، ويشترط فيه: أولاً: البل وغ فلا تصح الوصاية إلى الص بي منف رداً وتص ح إليه منض ماً إلى الكامل. ثانياً: العقل. ثالثاً: الاسلام إذا كان الموصي مسلماً. رابعاً: الوثوق بتنفيذه للوصية."},{"n":211,"p":44,"c":"الباب الثالث - الوصية","t":"الوصي أمين لا يضمن إلا إذا تع دّى أو فّرط والمقص ود بالتع دي هو التصرف في المال بما لمي أذن فيه الموصي -وم ن ذلك أن يتص رف فيه بما يخ الف مصلحة الموصي رعايةً للورثة أو لغيرهم -والمقص ود بالتفريط هو أن يهم ل حفظ المال على النهج المتعارف في حفظه فيؤدي الى تضرره أو تلفه."},{"n":212,"p":44,"c":"الباب الثالث - الوصية","t":"يص ّح جع لالوص اية إلى اثنين أو أكثر على نحو الانض مام أو الاس تقلال أو الترتيب. وإذا أوصى إلى اثنين بشرط الانضمام فاختلفا لمانع لدى كل منهما من الاتف اق مع الآخر، بحي ث كاني ؤدّي ذلك إلى تعطي لالعمل بالوصيّة، ض ّم القاضي -بموافق ة المرجع الديني -إليهم ا شخصاً آخر حسب ماي راه من المصلحة وينفذ ما يقرره اثنان من الثلاثة."},{"n":213,"p":44,"c":"الباب الثالث - الوصية","t":"يص ّح أن يوصي إلى اثنين أو أكثر ويجعل الوصاية إلى كل واحد في أمر بعينه لا يشاركه فيه الآخر."},{"n":214,"p":44,"c":"الباب الثالث - الوصية","t":"إذا جع لوص ياً مش روطاً بوص فخاص ص حت الوصية، وإذا زال الوص ف عن الوصي بطلت وص ايته، وص ار كمن لم يعين وص ياً، وي أتي حكمه في المادة (.)٢٢٤ ي قبل تنجيز تمام ما أوصي إليه به نص بالقاضي -بموافق ة"},{"n":215,"p":45,"c":"الباب الثالث - الوصية","t":"إذا مات الوص ّ المرجع الديني -وص يّاً لتنفي ذه.وك ذا إذا مات في حياة الموصي ولم يعلم هو بذلك أو علم ولم ينص بغيره ولم يكن مايد ّل على رجوعه عن أصل الوصيّة. ي أن يوصي إلى أحد في تنفيذ ما أوصي إليه به بعد موت ه،"},{"n":216,"p":45,"c":"الباب الثالث - الوصية","t":"ل يس للوص ّ ّإلا أن يكون مأذوناً من الموصي في الإيصاء إلى غيره. ي عزل نفسه عن الوصاية وجعلها لغيره بأن يص ير الغير وص يّاً"},{"n":217,"p":45,"c":"الباب الثالث - الوصية","t":"لا يح ّ ق للوص ّ عن الميّت بجعل من الوصي. ي أن يوكل أمر تنفيذ الوصيّة ّ - كلاً أو بعضاً -إلى غيرهم ّمن يوثق"},{"n":218,"p":45,"c":"الباب الثالث - الوصية","t":"يجوز للوص ّ بهّ، إلا أن تقوم القرينة على إرادة الموصي منه أن يباشره بنفسه، فلا يجوز له حينئ ٍذ ذلك."},{"n":219,"p":45,"c":"الباب الثالث - الوصية","t":"إذا عجز الوصي عن تنفيذ الوصية -ولو على سبيل توكي لغيره -ض م إليه القاضي -بموافق ة المرجع الديني -م ن يس اعده، وإذا ظه رت منه الخيانة ضم إليه أميناً يمنعه عن الخيانة فإن لم يمكن ذلك عزله ونصب غيره."},{"n":220,"p":45,"c":"الباب الثالث - الوصية","t":"إذا عين الموصي للوصي عم لاً خاص اً أو ق دراً خاصا أو كيفية خاصة وجب الاقتصار على ما عين والا كان خائناً.وإذا أطلق له التصرف عمل بنظره ولا بد من رعاية مصلحة الميت."},{"n":221,"p":45,"c":"الباب الثالث - الوصية","t":"إذا قال الموصي(: أنت وصيّي) ولم يعيّن شيئاً كان ظ اهراً في أنّه يريد كونه وصيّاً في إخراج الثلث وصرفه في مصلحة الموصي وأداء الحقوق التي عليه وأخذ الحقوق التي له ور ّد الأمانات والبضائع إلى أهلها وأخذها."},{"n":222,"p":45,"c":"الباب الثالث - الوصية","t":"يجوز للوصي أني رد الوصية في حال حياة الموصي بشرط أن يبلغه الرد، ولا يجوز له الرد بعد موت الموصي سواء قبلها قبل الرد أم لم يقبله ا. والرد السابق على الوصية لا أثر له ويستثنى من ذلك: اولاً: ما إذا أوصى إليه أن يباشر عملاً بنفسه كتغس يله وتكفينه ودفنه أو أداء الحج عنه ولو بأجرة، لا مجرد تولي تجهيز جنازته أو استنابة شخص عنه في الحج. ثانياً: ما إذا أوصى إليه أن يتولى أم راً مجان اً وكان مما يتولى بأجرة كرعاية أملاكه والإشراف على استحصال واردها وصرفه في موارده. ثالثاً: م ا إذا كان تنفيذ الوصية ض رورياً عليه بمقدار معتد به أو حرجي اً بحد بالغ. ففي هذه الموارد يجوز له أن ير ّد الوصية ولو لم يعلم بها في حياة الموص ي، ولو قبلها في حياته وبلغه القبول يلزمه عدم التخلف عن تنفيذها. ي أن يأخذ أجرة مثل عمله إذا كانت له أج رةّ، إلا إذا كان أوصي"},{"n":223,"p":46,"c":"الباب الثالث - الوصية","t":"يجوز للوص ّ صرح الموصي بذلك أو كانت قرينة عليه – وكان إليه بأن يعملم ّجاناً -كما لو ّ قد قبل ذلك، فلا يجوز له أخذ الأجرة حينئ ٍذ."},{"n":224,"p":46,"c":"الباب الثالث - الوصية","t":"إذا لم يع يّن الموصي وص ياً لتنفيذ وصيته، كم ا إذا أوصى بص رف ثلثه في الخي رات ولم يعين من يتولى ذلك، أو أوصى بثلثه للفق راء ولم يعين من يتولى توزيعه عل يهم، ف إن كان ظ اهر الوصية الإذن للورثة في تنفيذها جاز لهم ذلك، والا لزم الرجوع الى القاضي فينصب -بموافقة المرجع الديني -من يتولى تنفيذها ممن يوثق به."},{"n":225,"p":46,"c":"الباب الثالث - الوصية","t":"يج وز للموصي أن يجعلن اظراً على الوصي مش رفاً ومطلع اً على عمل ه. ووظيفته تابعة لجعل الموصي، وهو على قسمين: ي لأج لالاس تيثاق الأول -: ولعلّه الغالب -أن يجعل الناظر رقيب اً على الوص ّ على عمله بالوصيّة مطابق اً لما أوصى به حتّى أنّه لو رأى منه خلاف قرره الموصي اعترض عليه. ما ّ تصرفاته ومتابعة رأيه الوصي استئذانه في ومثل هذا الناظر لا يجب على ّ ّ ونظره فيها، بل إنّما يجب أن تكون أعماله با ّ وعلم منه. طلاعه ٍ الثاني: أن يجعل الناظر مشاوراً للوصي بحيث لا يعمل ّإلا بإذن منه وموافقت ه، ّ فالوصي وإن كان هو من يقوم بتنفيذ الوصية ولكن لا يمضي من أعماله ّ ّإلا ما وافق نظر الناظر وكان بإذنه، فلو عمل على نظره من دون موافقة تصرفه. الناظر لم ينفذ ّ الوصية بالولاية على الطفل"},{"n":226,"p":47,"c":"الباب الثالث - الوصية","t":"تص ح الوصية من الأب بالولاية على الطفل مع فقد الجد للأب ولا تصح مع وجوده.كم ا تص ّح الوصية بالولاية عليه من الجد للأب مع فقد الأب ولا تصح مع وجوده، ولا تصح الوصية بالولاية عليه من غيرهما."},{"n":227,"p":47,"c":"الباب الثالث - الوصية","t":"تك ون الولاية على الطفل بعد فقد الاب والجد للأب والوصي من أحدهما لمن يعينه القاضي بموافقة المرجع الديني، وي رجح بأن يقوم بتعي ين الأم إن كانت صالحة لذلك والا ع يّن غيرها ممن يكون ص الحاً ويتواف ق عليه أقرباء الطفل."},{"n":228,"p":47,"c":"الباب الثالث - الوصية","t":"إذا أوصى وصية تمليكية لطف ٍل بم اليكون أمر ذلك المال للأب والجد للأب مع وجود أحدهما ولمن يعينه القاضي -بموافق ة المرجع الديني مع فقدهما -ولا يحق للموصي أن يجعل أمر ذلك المال إلى غيرهم."},{"n":229,"p":47,"c":"الباب الثالث - الوصية","t":"إذا أوصى وصية تمليكية لطف ٍل على أن يبقى ماله بيد الوصي حتى يبلغ الطفل فيملكه إيّاه أو أن يصرفه عليه من دون أن يملكه إياه صح."},{"n":230,"p":47,"c":"الباب الثالث - الوصية","t":"يص ّح أن يجعل الأب أو الجد للأب الولاية والقيمومة على الأطف اللإثن ين أو أكثر، كما يجوز جعل ناظر على القيم المذكور بمعنى كونه مشرفا على عمله أو بمعنى كون العمل بنظره وموافقته."},{"n":231,"p":47,"c":"الباب الثالث - الوصية","t":"إذا لم يقيد الموصي الولاية بجهة بعينه اج از للوصي التصرف في جميع الش ؤون المتعلقة بالطف لمن حف ظ نفسه وتربيته وحف ظ أمواله والإنف اق عليه واس تيفاء ديونه ووف اء ما عليه من نفق ات أو ض مانات أو غير ذلك من الجهات."},{"n":232,"p":48,"c":"الباب الثالث - الوصية","t":"إذا قيد الموصي الولاية بجهة دون جهة وجب على الوصي الاقتصار على محل الإذن دون غيره من الجه ات وكان المرجع في الجه ات الأخ رى لمن يعينه القاضي بموافقة المرجع الديني. ثبوت الوصية"},{"n":233,"p":48,"c":"الباب الثالث - الوصية","t":"تثب ت الوصية التمليكية بشهادة رجل ين عدلين وبش هادة رجل ع دل مع يمين الموصى له وبشهادة رجل عدل مع امرأتين عدلين.وتق دم المقص ود بالعدل في المادة (.)١٢٥"},{"n":234,"p":48,"c":"الباب الثالث - الوصية","t":"تخ تص الوصية التمليكية بأنها تثبت بشهادة النس اء منف ردات فيثبت ربعها بشهادة امرأة عادلة ونصفها بشهادة امرأتين عادلتين وثلاثة أرباعها بشهادة ثلاث نساء عادلات وتمامها بشهادة أربع نساء ع ادلات بلا حاجة إلى اليم ين في شهادتهن."},{"n":235,"p":48,"c":"الباب الثالث - الوصية","t":"تثب ت الوصية التمليكية بإقرار الورثة جم يعهم إذا كانوا عق لاء بالغين وإن لم يكونوا ع دولاً.وإذا أقر بعضهم دون بعض تثبت بالنسبة إلى حصة المقر دون المنكر.وإذا أقر منهم اثنان وكانا عدلين ثبتت الوصية بتمامه ا، وإذا كان عدلاً واحداً تثبت أيضا مع يمين الموصى له."},{"n":236,"p":48,"c":"الباب الثالث - الوصية","t":"الوصية العهدية تثبت بشهادة رجلين عدلين فقط."},{"n":237,"p":48,"c":"الباب الثالث - الوصية","t":"تثب ت الوصية العهدية بإقرار الورثة جم يعهم، وإذا أقر بعضهم ثبت بعض الموصى به على نس بة حصة المقر وي نقص من حقه.وإذا أقر اثنان عدلان منهم ثبتت الوصية بتمامها."},{"n":238,"p":48,"c":"الباب الثالث - الوصية","t":"إذا وجد مكتوب بخط الميت أو بتوقيعه أو بصمة ابهامه يتضمن وصية عهدية أو تمليكية، وتأكدت سلامته من التزوير والتلاعب -كما إذا كان موثق اً بشهادة أشخاص معروفين بخطوطهم وتواقيعهم -يكفي ذلك في ثبوت تلك الوصية."},{"n":239,"p":49,"c":"الباب الرابع - الميراث › الفصل الأول - مقدمات الميراث","t":"الميراث هو التركة التي يخلفها الميت، وم ن يلحق به -وه والمفق ود الذي يبنى على موته بعد مضي مدة الانتظار وفقاً لما نصت عليه المادة (، )٣٣٠ وهي وتشمل: أولاً: ك لما يتركه الميت مما كان يملكه قبل موته، م ن أعي ان أو ديون أو منافع. ثانياً: كل ما يتركه الميت من حقوق تقبل الانتقال، كحق التحجير. ثالثاً: كل ما يملكه الميت بعد موته كالدية في قتل الخطأ، والدية في قتل العمد ي الدم الج اني، وم ا يملكه بعد موته إذا أوج دس ببه إذا ص الح عليها ول ّ قبل الموت."},{"n":240,"p":49,"c":"الباب الرابع - الميراث › الفصل الأول - مقدمات الميراث","t":"يخرج من التركة قبل تقسيمها، ما يأتي حسب الترتيب الآتي: أولاً: التجهيز الواجب للميت من الغسل والكفن والدفن. ثانياً: ال ديون، وه ي الأم وال التي اش تغلت بها ذمة الميت مثل المال الذي اقترضه والمبي ع الذي باعه سلفاً وثمن ما اش تراه نس يئة وع وض المض مونات وأروش الجناي ات ونحوها ومنها الخم سوالزك اة ور ّد المظالم. ثالثاً: الحج الواجب بالاستطاعة مع استقراره في الذمة. رابعاً: الوصية بما لا يزيد عن ثلث التركة، كما نصت عليه المادة (.)١٨٧ الفرع الاول موجبات الميراث"},{"n":241,"p":49,"c":"الباب الرابع - الميراث › الفصل الأول - مقدمات الميراث","t":"موجبات الميراث: اولاً: النسب، وهو: الاتصال بالميت بالولادة على وجه شرعي، وطبقاته ثلاث: أ.الطبقة الأولى: وهي صنفان: .١الأبوان المتّصلان دون الأجداد والجدّات..٢الأولاد وإن نزلوا ذكوراً وإناثاً. ب.الطبقة الثانية: وهي صنفان: .١الأجداد والجدّات وإن علوا..٢الإخوة والأخوات وأولادهم وإن نزلوا. ج.الطبقة الثالثة: صنف واحد وهم: الأعمام والأخوال وإن عل وا، كأعم ام الآباء والأ ّمهات وأخوالهم، وأعمام الأجداد والجدّات وأخ والهم، وك ذلك أولادهم وإن نزلوا كأولاد أولادهم، وأولاد أولاد أولادهم وهكذا بشرط صدق القرابة للميّت عرفاً. ثانياً: السبب: الزوجية والولاء. الفرع الثاني أنواع السهام"},{"n":242,"p":50,"c":"الباب الرابع - الميراث › الفصل الأول - مقدمات الميراث","t":"الفرض هو السهم المقدّر في الكتاب المجيد، وهو ستّة أنواع: الأول: النصف، وهو للبنت المنفردة، والأُخت للأبوين أو للأب فقط إذا لم يكن معها أخ أو جدّ، وللزوج مع عدم الولد للزوجة وإن نزل. الثاني: الربع، وهو للزوج مع الولد للزوجة وإن نزل، وللزوجة مع عدم الولد صت به ّ وإلا فهو بينهن بالسويّة. للزوج وإن نزل، فإن كانت واحدة اخت ّ صت الثالث: الثمن، وهو للزوجة مع الولد للزوج وإن نزل، فإن كانت واحدة اخت ّ به ّ وإلا فهو ّ لهن بالسويّة. الرابع: الثلث ان، وه وللبنت ين فصاعداً مع عدم الابن المس اوي، وللأُخت ين فصاعداً للأبوين أو للأب فقط مع عدم الأخ أو الجدّ. الخامس: الثل ث، وه وسهم الأ ُ ّم مع عدم الولد وإن نزل وعدم الإخوة على تفصيل يأتي، وللأخ والأُخت من الأ ُ ّم مع التعدّد إذا لم يكن معهما جدّ. السادس: السدس، وه ولك ّل واحد من الأبوين مع الولد وإن نزل، ول لأ ُ ّم مع الإخوة للأبوين أو للأب على تفصيل يأتي، ول لأخ الواح دمن الأ ُ ّم والأُخت الواحدة منها مع عدم الجدّ. الفرع الثالث اقسام الوارث"},{"n":243,"p":51,"c":"الباب الرابع - الميراث › الفصل الأول - مقدمات الميراث","t":"أقسام الوارث: الأولَ: من يرث بالفرض لا غير دائم اً، وه والزوجة فّ إن لها الربع مع عدم الولد، والثمن معه، ولا يُر ّد عليها أبداً. الثانيَ: من يرث بالفرض دائماً وربّما يرث معه بالردّ، ك الأ ُ ّم فّ إن لها السدس مع الولد والثلث مع عدمه إذا لم يكن حاج ب، وربّم ا ير ّد عليها زائ داً على الفرض كما إذا زادت التركة على السهام. وكالزوج فإنّه يرث الربع مع الولد والنصف مع عدمه، وي ر ّد عليه إذا لم يكن وارث ّإلا الإمام. الثال ثَ: م ن يرث بالفرضت ارةً وبالقرابة أُخ رى، ك الأب فإنّه يرث بالفرض مع وجود الولد وبالقرابة مع عدمه، والبنت والبنات فإنّهنّ يرثن مع الابن بالقرابة وبدونه بالفرض، والأُخت والأخوات للأب أو للأبوين فإنّهنّ يرثن مع الأخ بالقرابة ومع عدمه بالفرض، وكالإخوة والأخوات من الأ ُ ّم فإنّهم يرثون بالفرض إذا لم يكن ج ّد للأ ُ ّم وبالقرابة معه. الراب عَ: م ن لا يرث ّإلا بالقرابة، ك الابن، والإخ وة للأب وين أو للأب، والج ّد والأعمام والأخوال. الخامسَ: من لا يرث بالفرض ولا بالقرابة بل يرث بالولاء، وضمان الجريرة. الفرع الأول عدم الاسلام"},{"n":244,"p":52,"c":"الباب الرابع - الميراث › الفصل الثاني - موانع الإرث","t":"المسلم لا يرثه غير المسلم وان قرب منه."},{"n":245,"p":52,"c":"الباب الرابع - الميراث › الفصل الثاني - موانع الإرث","t":"غي ر المسلم لا يحجب من يتق رب به إذا كان مس لماً.فل ولم يكن للميت الا ابن غير مسلم وكان لهذا الابن ابن مس لم ورثه ابن ابنه.ول وم ات المسلم وفقد الوارث المسلم كان ميراثه للإمام (ع). ورث، وإذا أس لم"},{"n":246,"p":52,"c":"الباب الرابع - الميراث › الفصل الثاني - موانع الإرث","t":"إذا كان الوارث متع دداً وأس لم غير المسلم قبل القس مة ّ بعد القس مة أو مقارن اً لها لم يرث.وأم ا إذا كان الوارث واح دا فلاي رث، إلا إذا كان الواحد هو الزوجة وأس لمت قبل القس مة بينها وب ين الإمام (ع) فإنها ترث."},{"n":247,"p":52,"c":"الباب الرابع - الميراث › الفصل الثاني - موانع الإرث","t":"المسلمون يتوارثون وان اختلفوا في المذاهب والعقائد.وأما المنتحلون للإسلام المحكومون بعدمه كبعض الغلاة فهم لا يرثون من المسلم ويرث المسلم منهم."},{"n":248,"p":52,"c":"الباب الرابع - الميراث › الفصل الثاني - موانع الإرث","t":"الم راد من المسلم وغير المسلم وارث اً وموروث اً وحاجب اً ومحجوب اً أعم من المسلم وغير المسلم بالأص الة وبالتبعية كالطف لوالمجن ون، فك لطف لكان أحد أبويه مس لماً حال انعق اد نطفته بحكم المسلم، وك لطف لكان أب واه مع اً غير مس لمين حال انعق اد نطفته بحكم غير المسلم، إلا إذا أس لم أحد أبويه قبل بلوغه فإنه يتبعه في الإسلام ويجرى عليه حكم المسلمين. الفرع الثاني القتل"},{"n":249,"p":53,"c":"الباب الرابع - الميراث › الفصل الثاني - موانع الإرث","t":"القاتل لا يرث المقتول إذا كان القتل عمداً وظلماً."},{"n":250,"p":53,"c":"الباب الرابع - الميراث › الفصل الثاني - موانع الإرث","t":"القتل الخطأ، والقتل الخطأ الش بيه بالعمد -وه وما كان قاص داً لإيق اع الفع ل على المقتول غير قاصد للقت ل، وك ان الفع لمما لا يترت بعليه القتل في العادة -لا يمنع من إرث غير الدية."},{"n":251,"p":53,"c":"الباب الرابع - الميراث › الفصل الثاني - موانع الإرث","t":"القاتل لا يحجب من هو أبعد منه من الميت وإن كان يتصل من جهته به."},{"n":252,"p":53,"c":"الباب الرابع - الميراث › الفصل الثاني - موانع الإرث","t":"إذا انحصر الوارث في الطبقة الأولى بالولد القاتل الذي لا ذرية له انتق لارث المقتول إلى الطبقة الثانية وهم أجداده وأخوته ومع عدمهم فإلى الطبقة الثالثة، وإذا لم يكن له وارث كان ميراثه للإمام (عليه السلام). الفرع الثالث الولادة من الزنى"},{"n":253,"p":53,"c":"الباب الرابع - الميراث › الفصل الثاني - موانع الإرث","t":"الزنى هو الجماع -م ن غير إك راه -ب ين الرجل والم رأة الل ذين ليس بينهما علقة الزوجية مع الالتفات الى حرمته شرعاً حين ممارسته.ف إن كان الالتف ات الى ذلك من كلا الطرفين فالزنى منهما وإن كان من أحدهما -ب أن كان الآخر مشتبهاً -فالزنى من طرف الملتفت فقط."},{"n":254,"p":53,"c":"الباب الرابع - الميراث › الفصل الثاني - موانع الإرث","t":"لا توارث بين ولد الزنى وب ين أبيه الزاني ومن يتق رب به، ف لاي رثهم كما لا يرثونه، وكذلك لا توارث بينه وبين أمه الزانية ومن يتقرب بها."},{"n":255,"p":53,"c":"الباب الرابع - الميراث › الفصل الثاني - موانع الإرث","t":"يثبت الت وارث بين ولد الزنى وأقربائه من غير الزنى كالولد وكذلك الزوج أو الزوجة، فيرثهم ويرثونه. الفرع الأول ميراث الطبقة الأُولى"},{"n":256,"p":54,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"للأب المنفرد تمام تركة الميّت بالقرابة، وللأ ُ ّم المنفردة تمام تركته أيضاً، الثلث منها بالفرض والزائد عليه بالردّ.وإذا اجتمع أحد الأبوين مع الزوج كان له النصف، وإذا اجتمع مع الزوجة كان لها الربع ويكون الباقي لأحد الأبوين للأب قرابةً وللأ ُ ّم فرضاً ور ّداً."},{"n":257,"p":54,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع الأبوان وليس للميّت ولد ولا زوج أو زوجة كان للأ ُ ّم ثلث التركة فرضاً والباقي للأب إن لم يكن للأ ُ ّم حاج بمن إخوة الميّت أو أخوات ه، وأ ّما مع وجود الحاجب فللأ ُ ّم السدس والباقي للأب، ولا يرث الإخوة والأخوات شيئاً وإن حجبوا الأ ُ ّم عن الثلث."},{"n":258,"p":54,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا كان مع الأبوين زوج كان له النصف، وإذا كان معهما زوجة كان لها الربع، ويكون الثلث للأ ُ ّم مع عدم الحاجب والسدس معه والباقي للأب."},{"n":259,"p":54,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"يحج بالإخ وة أو الأخ وات الأ ُ ّم عن الثلث إلى السدس إذات وفّرت فيهم الشروط الآتية: الأول: وجود الأب حين موت الولد. الثاني: أن لا يقلّوا عن أخوين، أو أربع أخوات، أو أخ وأُختين. صة. الثالث: أن يكونوا إخوة الميّت لأبيه وأ ُ ّمه، أو للأب خا ّ الرابع: أن يكونوا مولودين فعلاً، فلا يكفي الحمل. الخامس: أن يكونوا مسلمين."},{"n":260,"p":54,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"للاب ن المنفرد تمام تركة الميّت بالقرابة، وللبن ت المنفردة تمام تركت ه، لكن النصف بالفرض والباقي بالردّ، وللابن ين المنف ردين فما زاد تمام التركة سم بينهم بالسويّة، وللبنت ين المنف ردتين فما زاد الثلثان فرضاً بالقرابة وتق ّ ّ ّ عليهن كذلك. بينهن بالسويّة والباقي ير ّد سم ويق ّ وللابن الأكبر في جميع الصور زيادةً على حص ته من التركة ثي اب بدن الميت وخاتمه وسيفه ومصحفه دون غيرها من مختصاته كساعته وكتبه."},{"n":261,"p":55,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع الابن والبنت منف ردين أو الأبناء والبنات منف ردين كان لهما أو لهم تمام التركة للذكر مثل ح ّ ظ الأُنثيين."},{"n":262,"p":55,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع الأبوان مع بنت واحدة فإن لم يكن للميّت إخوة -تتوفّر فيهم شروط سم المال خمسة أسهم، فلك ّل من الأبوين سهم واحد فرضاً الحجب المتقدّمة -ق ّ ور ّداً وللبنت ثلاثة أسهم فرضاً ورداً أيض اً، وأ ّما إذا كان للميّت إخوة تجتم ع فيهم شروط الحجب فهم يحجبون الأ ُ ّم حينئ ٍذ عن الر ّد فيكون لها السدس فقط سم البقيّة بين البنت والأب أرباع اً فرضاً ور ّداً سهم للأب وثلاثة سهام وتق ّ للبنت."},{"n":263,"p":55,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع الأبوان مع ابن واحد كان لك ٍ ّل من الأبوين السدس والباقي للاب ن، سم وإذا اجتمعا مع الأبناء أو البنات فقط كان لك ّل واحد منهما السدس والباقي يق ّ بين الأبناء أو البنات بالسويّة، وإذا اجتمعا مع الأولاد ذكوراً وإناثاً كان لك ٍ ّل سم الباقي بين الأولاد جميعاً للذكر مثل ح ّ ظ الأُنثيين. منهما السدس ويق ّ"},{"n":264,"p":55,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع أحد الأبوين مع البنت الواحدة كان لأحد الأبوين الربع فرضاً ور ّداً والباقي للبنت كذلك، وإذا اجتمع أحد الأبوين مع البنتين فما زاد كان له الخمس سم بينهنّ بالسويّة. فرضاً ور ّداً والباقي للبنتين أو البنات بالفرض والرد يق ّ ّ"},{"n":265,"p":55,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع أحد الأبوين مع ابن واحد كان له السدس فرضاً والباقي للاب ن، سم وإذا اجتمع أحد الأبوين مع الأولاد الذكور كان له السدس فرضاً والباقي يق ّ بين الأبناء بالسويّة، ولو كان مع الابن الواحد أو الأبناء بنت أو بنات كان لأحد سم بين الأولاد للذكر مثل ح ّ ظ الأُنثيين. الأبوين السدس فرضاً والباقي يق ّ"},{"n":266,"p":55,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع أحد الأبوين مع أحد الزوجين ومعهما البنت الواحدة كان للزوج سم الباقي أرباع اً ربع لأحد الأبوين فرضاً ور ّداً الربع وللزوجة الثمن، ويق ّ والباقي للبنت كذلك. وإذا كان معهما بنتان فما زاد فلأحد الزوجين نصيبه الأدنى، ف إن كان زوجة سم الباقي أخماس اً خم سلأحد الأبوين فرضاً ور ّداً وأربعة فلها الثمن ويق ّ أخماس للبنتين فما زاد كذلك، وإن كان زوجاً فله الربع ولأحد الأبوين السدس ّ عليهن. والبقيّة للبنتين فصاعداً فير ّد النقص وإذا كان معهما ابن واحد أو متع دّد أو أبن اء وبنات فلأحد الزوجين نصيبه الأدنى من الربع أو الثمن ولأحد الأبوين السدس والباقي للبقيّة، ومع الاختلاف فللذكر مثل حظّ الأُنثيين."},{"n":267,"p":56,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع الأبوان والبنت الواحدة مع أحد الزوجين، فإن كان زوجاً فله الربع وللأبوين السدسان والباقي للبنت في نقص من فرض ها -وه والنصف -نص ف سم الباقي أخماساً يكون لك ٍ ّل من الأبوين السدس، وإن كان زوجة فلها الثمن ويق ّ سهم واحد فرضاً ور ّداً وثلاثة أسهم للبنت كذلك، ه ذا إذا لم يكن للميّت إخوة تتوفّر فيهم شروط الحجب ّ وإلا فإنّهم يحجبون الأ ُ ّم عن الر ّد فيكون لها السدس سم الباقي بين الأب والبنت أرباعاً. ويق ّ"},{"n":268,"p":56,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع الأبوان وبنتان فصاعداً مع أحد الزوجين فللزوج أو الزوجة النصيب الأدنى من الربع أو الثمن والسدس ان للأب وين ويكون الباقي للبنتين فصاعداً ّ ّ عليهن بمقدّر نصيب الزوجين: الربع إن كان بينهن بالسويّة فيرد النقص سم يق ّ زوجاً والثمن إن كان زوجة. وإذا كان مك ان البنت ين فص اعداً ابن واحد أو متع دّد أو أبن اء وبنات فلأحد الزوجين نصيبه الأدنى من الربع أو الثمن وللأبوين السدسان، والب اقي للولد أو الأولاد ومع الاختلاف يكون للذكر ضعف ح ّ ظ الأُنثى."},{"n":269,"p":56,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع أحد الزوجين مع ولد واحد أو أولاد متع دّدين، فلأح دهما نصيبه الأدنى من الثمن أو الربع والباقي للولد أو الأولاد، وم ع الاختلاف يكون للذكر مثل ح ّ ظ الأُنثيين."},{"n":270,"p":56,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"أولاد الأولاد وإن نزلوا يقوم ون مق ام الأولاد في مقاس مة الأبوين وحجبهما عن أعلى الس همين إلى أدناهما، ومن ع من ع داهم من الأق ارب، ولا يشترط في توريثهم فقد الأبوين."},{"n":271,"p":57,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"لا يرث أولاد الأولاد إذا كان للميّت ولد وإن كان أُنثى، فإذا ترك بنت اً وابن ابن كان الميراث للبنت. ولكن ينبغي مؤكداً لمن مات بعض أولاده في حياته وله ذرية أن يوصي بإخراج حصة له من ثلثه -أو من خ ارج الثلث مع استحص الموافقة الورثة عليه في حال حياته -تماثل حصته لو كان حياً بعد وفاته وتمنح تلك الحصة لذريته."},{"n":272,"p":57,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"أولاد الأولاد مترتّبون في الإرث، ف الأقرب منهم يمنع الأبعد، ف إذا كان للميّت الولَد. الولَد دون َولَ ِد َولَ ِد َ لولَ ِد َ وولَ ُد َولَ ِد َولَدٍ، كان الميراث َ َولَ ُد َولَ ٍد َ يتقربون به، فيرث ولد البنت نصيب أ ُ ّمه ذكراً كان"},{"n":273,"p":57,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"يرث أولاد الأولاد نصيب من ّ أم أُنثى وهو النصف سواء انف رد أو كان مع الأبوين وير ّد عليه كما ير ّد على أ ُ ّمه لو كانت موجودة. ويرث ولد الابن نصيب أبيه ذكراً كان أم أُنثى، فإن انف رد كان له جميع الم ال، ولو كان معه ذو فرض فله ما فَ ُ صته. ض َل عن ح ّ سم"},{"n":274,"p":57,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"لو كان للميّت أولاد بنت وأولاد ابن كان لأولاد البنت الثلث نصيب أ ُ ّمهم يق ّ بينهم للذكر مثل ح ّ سم ظ الأُنثي ين، ولأولاد الابن الثلثان نصيب أب يهم يق ّ بينهم كذلك."},{"n":275,"p":57,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إنّ أولاد الأولاد عند فقد الأولاد يشاركون أبوي الميّت في الميراث. فإذا ترك أبوين وولد ابن كان لك ٍ ّل من الأبوين السدس ولولد الابن الباقي. وإذا ترك أبوين وأولاد بنت كان للأبوين السدسان ولأولاد البنت النصف وير ّد السدس على الجميع بالنسبة إذا لم يكن للميّت إخوة تتوفّر فيهم شروط الحجب، سم مجموع التركة أخماساً، ثلاثة منها لأولاد البنت فرضاً ور ّداً، واثنان منها فيق ّ للأبوين كذلك، وإذا كان للميّت إخوة تتوفّر فيهم شروط الحجب فإنّهم يحجبون الأ ُ ّم عن الر ّد فيكون لها السدس. وإذا ترك أحد الأبوين مع أولاد بنت كان لأولاد البنت ثلاثة أرباع التركة فرضاً ور ّداً والربع الرابع لأحد الأبوين كذلك كما تقدّم فيما إذا ترك أحد الأبوين وبنتاً، وهكذا الحكم في بقيّة الصور. وإذا ترك زوجاً وأبوين وأولاد بنت كان للزوج الربع وللأبوين السدسان ولأولاد البنت سدسان ونصف سدس في نقص عن سهم البنت -وه والنصف -نص ف سدس في رد النقص على أولاد البنت كماي رد على البنت فيما إذا ترك زوجاً وأبوين وبنتاً. الفرع الثاني ميراث الطبقة الثانية"},{"n":276,"p":58,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"لا يرث أهل هذه الطبقة ّإلا إذا لم يكن للميّت وارث من الطبقة الأولى."},{"n":277,"p":58,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا لم يكن للميّت قري بمن الطبقة الثانية غير أخيه لأبويه ورث المال كلّه بالقرابة، ومع التعدّد ينقسم بينهم بالسويّة."},{"n":278,"p":58,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"للأُخ ت المنفردة من الأبوين المال كلّه، ت رث نص فه بالفرض ونص فه الآخر ر ّداً بالقرابة، وللأُختين أو الأخوات من الأبوين المال كلّه يرثن ثلثيه بالفرض والثلث الثالثر ّداً بالقرابة."},{"n":279,"p":58,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا ترك الميت أخ اً واح داً أو أكثر من الأبوين مع أُخت واحدة أو أكثر كذلك فلا فرض بل يرثون المال كلّه بالقرابة يقتسمونه بينهم للذكر مثل ح ّ ظ الأُنثيين."},{"n":280,"p":58,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"لا يرث الأخ أو الأُخت للأب مع وجود الأخ والأُخت للأبوين، ومع فقدهم يرثون على نهج ميراثهم، فللأخ من الأب واحداً كان أو متع دّداً تمام المال بالقراب ة، وللأُخت الواحدة النصف بالفرض والنصف الآخر بالقرابة، وللأخ وات المتعدّدات تمام المال يرثن ثلثيه بالفرض والباقير ّداً بالقرابة. سمونه بينهم وإذا اجتمع الإخوة والأخوات كلّهم للأب كان لهم تمام المال يق ّ للذكر مثل ح ّ ظ الأُنثيين."},{"n":281,"p":58,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"ل لأخ المنفرد من الأ ُ ّم أو الأُخت المنفردة المال كلّه يرث السدس بالفرض والباقير ّداً بالقرابة، وللاثنين فصاعداً من الإخوة للأ ُ ّم ذكوراً أو إناثاً أو ذكوراً سم بينهم وإناثاً المال كلّه يرثون ثلثه بالفرض والباقير ّداً بالقرابة، ويق ّ فرضاً ور ّداً بالسويّة."},{"n":282,"p":59,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع الإخوة بعضهم من الأبوين وبعضهم من الأ ُ ّم فإن كان الذي من الأ ُ ّم واحداً كان له السدس ذكراً كان أو أُنثى والباقي لمن كان من الأب وين، سم بينهم بالسويّة ذكوراً كانوا وإن كان الذي من الأ ُ ّم متعدّداً كان لهم الثلث يق ّ أو إناثاً، أو ذكوراً وإناثاً، والباقي لمن كان من الأبوين واح داً كان أو متع دّداً، سم بالسويّة، وم ع الاختلاف فيهما ومع اتّف اقهم في الذكورة والأُنوثة يق ّ سم للذكر مثل ح ّ ظ الأُنثيين. يق ّ قرب بالأبوين إناثاً وكون الأخ من الأ ُ ّم واح داً كان ميراث وفي صورة كون المت ّ الأخ وات من الأبوين بالفرض ثلث ين وبالقرابة السدس، وإذا كان المتق ّرب بالأبوين أُنثى واحدة كان لها النصف فرضاً، وم ا زاد على سهم المتق ّرب بالأ ُ ّم وهو السدس أو الثلثر ّداً عليها ولا ير ّد على المتق ّرب بالأ ُ ّم، وإذا وجد معهم إخوة من الأب فقط فلا ميراث لهم."},{"n":283,"p":59,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا لم يوجد للميّت إخوة من الأبوين وكان له إخوة بعضهم من الأب فقط وبعضهم من الأ ُ ّم فقط، فإذا كان الأخ من الأ ُ ّم واح داً كان له السدس، وإذا كان سم بينهم بالسويّة، والباقي الزائد على السدس أو الثلث متعدّداً كان لهم الثلث يق ّ سم بينهم للذكر مثل ح ّ ظ الأُنثي ين مع اخ تلافهم في يكون للإخ وة من الأب يق ّ سم بينهم بالسويّة. الذكورة والأُنوثة، ومع عدم الاختلاف فيهما يق ّ المتقرب بالأب أُنثى واحدة يكون أيضاً ميراثها ما زاد وفي الصورة التي يكون ّ المتقرب بالأ ُ ّم بعضه بالفرض وبعضه بالر ّد بالقرابة. على سهم ّ"},{"n":284,"p":59,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"في جميع ص ور انحص ار الوارث القري بب الإخوة -س واء أك انوا من الأبوين أم من الأب أم من الأ ُ ّم، أم بعضهم من الأبوين وبعضهم من الأب وبعضهم من الأ ُ ّم -إذا كان للميّت زوج كان له النصف، وإذا كانت له زوجة كان لها الربع وللأخ من الأ ُ ّم مع الاتّحاد السدس ومع التعدّد الثلث والباقي للإخ وة من الأبوين أو من الأب إذا كانوا ذكوراً أو ذكوراً وإناثاً. وأ ّما إذا كانوا إناثاً ففي بعض الص ور تكون الف روض أكثر من الفريضة -، كم ا إذا ترك زوجاً أو زوجة وأُخت ين من الأبوين أو الأب وأُخت ين أو أخ وين من الأ ُ ّم -ف ّ إن سهم المتق ّرب بالأ ُ ّم الثلث وس هم الأُخت ين من الأبوين أو الأب الثلثان، وذل كتم ام الفريضة ويزيد عليها سهم الزوج أو الزوجة. وإذا ترك زوجاً وأُخت اً واحدة من الأبوين أو الأب وأُخت ين أو أخ وين من الأ ُ ّم فإنّ نصف الزوج ونصف الأُخت من الأبوين يس توفيان الفريضة ويزيد عليها المتقرب بالأ ُ ّم. سهم ّ صة ففي مثل هذه الف روض يدخل النقص على المتق ّرب بالأبوين أو بالأب خا ّ المتقرب بالأ ُ ّم ولا على الزوج أو الزوجة. ولا يدخل النقص على ّ وفي بعض الص ور تكون الفريضة أكثر، كم ا إذا ترك زوجة وأُخت اً من الأبوين وأخ اً أو أُخت اً من الأ ُ ّم، ف ّ إن الفريضة تزيد على الف روض بنص فسدس فير ّد على الأُخت من الأبوين، فيك ون لها نصف التركة ونصف سدسها وللزوجة الربع وللأخ أو الأُخت من الأ ُ ّم السدس."},{"n":285,"p":60,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا لم يكن للميّت قري بمن الطبقة الثانية غير ج ّد أوج ّدة لأب أو لأ ُ ّم كان له المال كلّه، وإذا اجتمع الج ّد والج دّة مع اً فإن كان الأب كان المال لهما سم سم بينهما للذكر ضعف الأُنثى، وإن كان الأ ُ ّم فالم الأيضاً لهما لكن يق ّ يق ّ بينهما بالسويّة.وإذا اجتمع الأجداد بعضهم للأ ُ ّم وبعضهم للأب كان للج ّد للأ ُ ّم الثلث -وإن كان واح داً -وللج ّد للأب الثلثان، ولا فرق فيما ذكر بين الج ّد الأدنى والأعلى."},{"n":286,"p":60,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع الزوج أو الزوجة مع الأجداد كان للزوج النصف وللزوجة الربع للمتقرب بالأب. المتقرب بالأ ُ ّم الثلث، والباقي من التركة ويعطى ّ ّ"},{"n":287,"p":60,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع الإخوة مع الأجداد فالج ّد وإن علا كالأخ والج دّة وإن علت كالأُخ ت، فالج ّد وإن علا يقاسم الإخوة وكذلك الج دّة، ف إذا اجتمع الإخوة والأج داد فإ ّما أن يتّحد نوع كٍ ّل منهما مع الاتّح اد في جهة النسب، ب أن يكون الأجداد والإخوة كلّهم للأب أو كلّهم للأ ُ ّم، أو مع الاختلاف فيها كأن يكون الأجداد للأب والإخوة للأ ُ ّم، وإ ّما أن يتعدّد نوع كٍ ّل منهما بأن يكون كّل من الأجداد والإخوة بعضهم للأب وبعضهم؛ للأ ُ ّم، أو يتع دّد نوع أحدهما ويتّحد الآخر، ب أن يكون الأجداد نوعين بعضهم للأب وبعضهم للأ ُ ّم والإخوة للأب لا غير أو للأ ُ ّم لا غير، أو يكون الإخوة بعضهم للأب وبعضهم للأ ُ ّم، والأجداد كلّهم للأب لا غير أو للأ ُ ّم إن كّلاً منهما إ ّما أن يكون واح داً ذكراً أو أُنثى أو متع دّداً ذكوراً لا غير، ث ُ َّم ّ أو إناثاً أو ذكوراً وإناثاً.فتوجد صور تسع كما يأتي: اولاً: إذا اجتمع الج ّد واح داً كان -ذك راً أو أُنثى -أم متع دّداً ذكوراً أو إناثاً أو ذكوراً وإناثاً من قبل الأ ُ ّم، مع الأخ على أحد الأقسام الم ذكورة من قبل الأ ُ ّم أيضاً اقتسموا المال بالسويّة. ثانياً: إذا اجتمع الج ّد والأخ -على أحد الأقسام المذكورة فيهما -م ن قبل الأب اقتسموا المال بالسويّة إن كانوا جميعاً ذكوراً أو إناث اً، وإن اختلف وا في الذكورة والأُنوثة اقتسموا المال بالتفاضل للذكر مثل ح ّ ظ الأُنثيين. ثالثاً: إذا اجتمع الأجداد من قبل الأب والأج داد من قبل الأ ُ ّم -ذك وراً كانوا أو إناثاً أو ذكوراً وإناثاً -مع الإخوة كذلك بعضهم للأب وبعضهم للأ ُ ّم ذكوراً فللمتقرب بالأ ُ ّم من الإخوة والأج داد جميعاً الثلث أو إناثاً أو ذكوراً وإناثاً، ّ وللمتقرب بالأب منهم جميعاً الثلثان يقتسمونهما للذكر يقتسمونه بالسويّة، ّ مثل ح ّ ظ الأُنثيين -مع الاختلاف بالذكورة والأُنوثة ّ - وإلا فبالسويّة. رابعاً: إذا اجتمع الج ُّد على أحد الأقسام الم ذكورة للأب مع الأخ على أحد الأقسام الم ذكورة أيضاً للأ ُ ّم، يك ون للأخ السدس إن كان واح داً والثلث سم بينهم بالسويّة، ويك ون الباقي للج ّد واح داً كان إن كان متع دّداً يق ّ أو متعدّداً، ومع الاختلاف في الذكورة والأُنوثة يقتسمونه بالتفاضل. خامساً: إذا اجتمع الج ّد بأحد أقس امه الم ذكورة للأ ُ ّم مع الأخ للأب يكون سم بينهم بالسويّة مطلق اً، ول لأخ الثلثان للج ّد الثلث، وفي صورة التعدّد يق ّ ومع التعدّد والاختلاف يكون للذكر ضعف ح ّ ظ الأُنثى. وإذا كانت مع الج ّد للأ ُ ّم أُخت للأب فإن كانتا اثنتين فما زاد لم تزد الفريضة على السهام، وإن كانت واحدة كان لها النصف وللج ّد الثلث، وف ي السدس الزائد من التركة لا بد من التصالح بخصوصه بين الأُخت والجدّ. سادساً: إذا اجتمع الأجداد من قبل الأب والأج داد من قبل الأ ُ ّم مع أخ أو أكثر لأب، ك ان للج ّد للأ ُ ّم -وإن كان أُنثى واحدة -الثل ث، وم ع تعدّد الج ّد يقتسمونه بالسويّة ولو مع الاختلاف في الذكورة والأُنوثة، والثلثان للأجداد للأب مع الإخوة له يقتسمونه للذكر ضعف ح ّ ظ الأُنثى. سابعاً: إذا اجتمع الأجداد من قبل الأب والأج داد من قبل الأ ُ ّم مع أخ لأ ُ ّم، ك ان للج ّد للأ ُ ّم مع الأخ للأ ُ ّم الثلث بالسويّة ولو مع الاختلاف بالذكورة والأُنوث ة، وللأجداد للأب الثلثان للذكر مثل ح ّ ظ الأُنثيين. ثامن اً: إذا اجتمع الأجداد من قبل الأب والإخوة من قبل الأب والإخوة من قبل الأ ُ ّم، فل لأخ للأ ُ ّم السدس إن كان واح داً، والثل ث إن كان متع دّداً يقتسمونه بالسويّة، وللإخ وة للأب مع الأجداد للأب الب اقي، ومع الاختلاف في الذكورة والأُنوثة يكون للذكر ضعف ح ّ ظ الأُنثى. تاسعاً: إذا اجتمع الأجداد من قبل الأ ُ ّم والإخوة من قبل الأب والإخوة من قبل الأ ُ ّم كان للج ّد مع الإخوة للأ ُ ّم الثلث بالسويّة وللإخ وة للأب الباقي للذكر مثل ح ّ ظ الأُنثيين."},{"n":288,"p":62,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"أولاد الإخوة لا يرثون مع الإخوة شيئاً فلا يرث ابن الأخ للأب وين مع الأخ من الأب أو الأ ُ ّم بل الميراث للأخ، ه ذا إذا زاحمه وأ ّما إذا لم يزاحمه كما إذا ترك ج ّداً لأ ُ ّم وابن أخ لأ ُ ّم أيضاً مع أخ لأب فابن الأخ يرث مع الج ّد الثلث، والثلثان للأخ. تق ام أولادهم مق امهم في الإرث وفي مقاس مة الأج داد،"},{"n":289,"p":62,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا فُقد إخ وةُ المي ِ وك ّل واحد من الأولاد يرث نصيب من يتق ّرب به، فل وخل فالميّت أولاد أخ أو أُخت لأ ُ ّم لا غير كان لهم سدس أب يهم أو أ ُ ّمهم بالفرض والباقي بالردّ، ولو خل فأولاد أخ وين أو أُخت ين أو أخ وأُخت لأ ُ ّم كان لأولاد كّل واحد من الإخوة السدس بالفرض وسدس ان بالردّ، ول وخل فأولاد ثلاثة إخوة صة أبيه أو أ ُ ّمه، وهك ذا الحكم في أولاد كان لك ّل فريق من أولاد واحد منهم ح ّ الإخوة للأبوين أو للأب. سم المال بينهم بالسويّة إن كانوا أولاد أخ لأ ُ ّم وإن اختلف وا ويق ّ بالذكورة والأُنوثة. ويكون التقس يم بالتفاضل للذكر مثل ح ّ ظ الأُنثي ين إن كانوا أولاد أخ للأبوين أو للأب."},{"n":290,"p":63,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا خلف الميّت أولاد أخ لأ ُ ّم وأولاد أخ للأب وين أو للأب، ك ان لأولاد الأخ للأ ُ ّم السدس وإن كثروا، ولأولاد الأخ للأبوين أو للأب الباقي وإن قلّوا. ص لب ّيون كان الميراث"},{"n":291,"p":63,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا لم يكن للميّت إخوة ولا أولاد إخوة ُ لأولاد أولاد الإخوة. الفرع الثالث ميراث الطبقة الثالثة"},{"n":292,"p":63,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"لا يرث أهل هذه الطبقة مع وجود الطبقة الأُولى أو الثانية، وه م ص نف واحد يمنع الأقرب منهم الأبعد. سم بينهم بالس ويّة،"},{"n":293,"p":63,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"للع ّم المنفرد تمام المال، وك ذا للع ّم ين فما زاد يق ّ وكذا الع ّمة والع ّمتان والع ّمات لأب كانوا أم لأ ُ ّم أم لهما. سم المال بينهم"},{"n":294,"p":63,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع الذكور والإناث كالع ّم والع ّمة والأعمام والع ّمات، فيق ّ بالتفاضل للذكر مثل ح ّ ظ الأُنثي ين إن كانوا جميعاً لأب وين أو لأب، وإن كانوا جميعا لأ ُ ّم، فيقسم المال بينهم بالسوية. وتفرقوا في جهة النسب بأن كان بعضهم للأب وين"},{"n":295,"p":63,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع الأعمام والع ّمات ّ المتقرب بالأبوين المتقرب بالأب، ولو فقد وبعضهم للأب وبعضهم للأ ُ ّم لم يرثه ّ ّ المتقرب بالأ ُ ّم فإن كان واح داً كان له الس دس، المتقرب بالأب مقامه، وأ ّما قام ّ ّ سم بينهم بالتفاضل للذكر ضعف ح ّ ظ الأُنث ى، وإن كان متعدّداً كان لهم الثلث يق ّ للمتقرب بالأبوين واح داً كان أو أكثر وأ ّما الزائد على السدس أو الثلث فيكون ّ سم بينهم للذكر مثل ح ّ ظ الأُنثيين. يق ّ سم بينهم بالسويّة، وللخال ة"},{"n":296,"p":64,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"للخال المنفرد المال كلّه وكذا الخ الان فما زاد يق ّ المنفردة المال كلّه وكذا الخالتان والخالات، وإذا اجتمع الذكور والإناث بأن كان للميّت خال فما زاد وخالة فما زاد -سواء أكانوا جميعاً للأبوين أم جميعاً للأب أم جميعاً للأ ُ ّم – يكون للخ النصف التركة وللخالة ثلثها ولا بدمن التص الح بين الطرفين بخصوص السدس الباقي. وتفرقوا في جهة النسب بأن كان بعضهم للأب وين"},{"n":297,"p":64,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع الأخوال والخالات ّ فالمتقربون بالأب -أي الخال المتّحد مع أ ُ ّم الميّت وبعضهم للأب وبعضهم للأ ُ ّم، ّ في الأب فقط – لا يرثون وينحصر الإرث بالب اقين فللمتق ّرب بالأ ُ ّم السدس سم بينهم بالسويّة، ويك ون الباقي إن كان واح داً، والثل ث إن كان متع دّداً يق ّ سم بينهم بالسويّة. للمتقرب بالأبوين يق ّ ّ"},{"n":298,"p":64,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع الأعمام والأخوال كان للأخوال الثلث وإن كان واح داً ذكراً أو أُنث ى، والثلثان للأعمام وإن كان واحداً ذكراً أو أُنثى، ف إن تعدّد الأخ وال يكون نصف الثلث لل ذكور منهم وثلثه للإن اث ولا بدمن التص الح بين الطرفين بخصوص السدس الباقي، وإذا تعدّد الأعمام اقتسموا الثلثين بينهم بالتفاضل."},{"n":299,"p":64,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"أولاد الأعمام والع ّمات والأخوال والخالات يقوم ون مق ام آب ائهم عند فق دهم، فلا يرث ولد ع ّم أو ع ّمة مع ع ّم ولا مع ع ّمة ولا مع خال ولا مع خال ة، ولا يرث ولد خال أو خالة مع خال ولا مع خالة ولا مع ع ّم ولا مع ع ّم ة، بل يكون الميراث للع ّم أو الخال أو الع ّمة أو الخالة. ويستثنى من ذلك صورة واحدة وهي أن يترك الميّت ابن ع ّم لأبوين مع ع ّم لأب فإنّ ابن الع ّم يمنع الع ّم ويكون المال كلّه له ولا يرث معه الع ّم للأب أص لاً، ولو كان معهما خال أو خالة سقط ابن الع ّم وكان الميراث للع ّم والخال والخالة، ولو تعدّد الع ّم أو ابن الع ّم أو انض ّم إليهما زوج أو زوجة فلا بدمن التص الح بين الأعمام وابناء الع ّم بخصوص الميراث."},{"n":300,"p":64,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"ي رث كّل واحد من أولاد العُمومة وال ُخؤولة نصيب من يتق ّرب به، فإذا اجتمع ولد ع ّمة وولد خال أخذ ولد الع ّمة -وإن كان واحداً أُنثى -الثلث ين، وولد الخال -وإن كان ذكراً متع دّداً -الثل ث، والقس مة بين أولاد العُمومة أو الُخؤولة على النحو المتقدّم في أولاد الإخوة في المادة (.)٢٨٩"},{"n":301,"p":65,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"الأقرب من العمومة والخؤولة يمنع الأبعد منهما، فإذا كان للميّت ع ّم وع ّم أب أو ع ّم أ ُ ّم أو خال أب أو أ ُ ّم مثلاً كان الميراث لع ّم الميّت، ولا يرث معه ع ّم أبيه ولا خال أبيه ولا ع ّم أ ُ ّمه ولا خال أ ُ ّمه، ولو لم يكن للميّت ع ّم أو خال لكن كان له ع ّم أب وع ّم ج ّد أو خال ج ّد مثلاً كان الميراث لع ّم الأب دون ع ّم الج ّد أو خاله."},{"n":302,"p":65,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"أولاد ع ّم الميّت وع ّمته وخاله وخالته مقدّمون على أعمام أبيه وأ ُ ّمه وع ّماتهما وأخوالهما وخالاتهما، وك ذلك من نزلوا من الأولاد وإن بع دوا فإنّهم مق دّمون على الدرجة الثانية من الأعمام والع ّمات والأخوال والخالات."},{"n":303,"p":65,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع ع ّم الأب وع ّمته وخاله وخالته وع ّم الأ ُ ّم وع ّمتها وخالها وخالتها سم بينهم بالسويّة لا بالتفاضل، ويك ون الثلثان كان للمتق ّرب بالأ ُ ّم الثلث ويق ّ سم بينهما بالس ويّة، للمتق ّرب بالأب فيعطى ثلثهم الخال أبيه وخالته يق ّ سم بينهما بالتفاضل للذكر مثل ح ّ ظ الأُنثيين. ويعطى الباقي لع ّم أبيه وع ّمته، ويق ّ"},{"n":304,"p":65,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا دخل الزوج أو الزوجة على الأعمام والأخوال كان للزوج أو الزوجة نصيبه الأعلى من النصف أو الربع وللأخوال الثلث وللأعمام الباقي، وأ ّما قسمة الثلث بين الأخوال وكذلك قسمة الباقي بين الأعمام فعلى ما تقدّم."},{"n":305,"p":65,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا دخل الزوج أو الزوجة على الأخوال فقط وكانوا متعدّدين أخذ نصيبه الأعلى سم بينهم على ما تقدّم، وهك ذا الحكم من النصف أو الربع والباقي يق ّ فيما لو دخل الزوج أو الزوجة على الأعمام المتعدّدين."},{"n":306,"p":65,"c":"الباب الرابع - الميراث › الفصل الثالث - الميراث حسب الطبقات","t":"إذا اجتمع لوارث سببان للمي راث فإن لم يمنع أحدهما الآخر ورث بهما مع اً تزوج أخو الشخص سواء اتّحدا في النوع كج ّد لأب هو ج ّد لأ ُ ّم أم تع ّددا كما إذا ّ زوج ع ّم وخ ال لأبيه أُخته لأ ُ ّمه فولدت له فه ذا الشخص بالنسبة إلى ولد المت ّ وولد الشخص بالنسبة إلى ول دهما ولد ع ّم لأب وولد خال لأ ُ ّم، وإذا من ع أحد تزوج الاخوان زوجتين فولدتا لهماث ُ َّم مات السببين الآخر ورث بالمانع، كما إذا ّ الأول زوج الآخر زوجته فول دت له، فول د هذه المرأة من زوجها ّ أحدهما فت ّ خوة لا بالعمومة. ابن ع ّم لولدها من زوجها الثاني وأخ لأ ُ ّم فيرث بالأ ُ ّ"},{"n":307,"p":66,"c":"الباب الرابع - الميراث › الفصل الرابع - ميراث الزوج والزوجة","t":"يرث الزوج من زوجته نصف تركتها إذا لم يكن لها ولد، ويرث الربع مع الولد وإن نزل، وترث الزوجة من زوجها ربع تركته إذا لم يكن له ولد، وترث الثمن مع الولد وإن نزل."},{"n":308,"p":66,"c":"الباب الرابع - الميراث › الفصل الرابع - ميراث الزوج والزوجة","t":"إذا لم تت رك الزوجة وارث اً لها ذا نسب أو سبب ّإلا الإمام (علي ه الس لام) فالنصف لزوجها بالفرض والنصف الأخر ير ّد عليه، وإذا لم يترك الزوج وارث اً له ذا نسب أو سبب ّإلا الإمام (عليه السلام) فلزوجته الربع والباقي يكون للإمام (علي ه الس لام) ويص رف بإذن المرجع الديني فيت أمين الح وائج الض رورية للمؤمنين."},{"n":309,"p":66,"c":"الباب الرابع - الميراث › الفصل الرابع - ميراث الزوج والزوجة","t":"إذا كانت للميّت زوجتان فما زاد اش تركن في الثمن بالسويّة مع وجود الولد للزوج، وفي الربع بالسويّة مع عدم الولد له."},{"n":310,"p":66,"c":"الباب الرابع - الميراث › الفصل الرابع - ميراث الزوج والزوجة","t":"لا يشترط في التوارث بين الزوجين الدخول، فيتوارثان ولو مع عدم الدخول. زوج الم ريض ولم يدخل بالمرأة ولم يب رأ من مرضه حتّى مات"},{"n":311,"p":66,"c":"الباب الرابع - الميراث › الفصل الرابع - ميراث الزوج والزوجة","t":"إذا ت ّ به فزواجه باطل فلا مهر لها ولا ميراث. الرجعي ما دامت العدّة باقية، ف إذا انتهت"},{"n":312,"p":66,"c":"الباب الرابع - الميراث › الفصل الرابع - ميراث الزوج والزوجة","t":"يتوارث الزوجان إذا انفصلا بالطلاق ّ أو كان الطلاق بائناً فلا توارث.وعلى ذلك فلا توارث بين الزوجين إذا انفص لا بالطلاق الخلعي ومات أحدهما في العدّةّ، إلا إذا رجعت المختلعة في الفدية فمات أحدهما بعد ذلك قبل انقضائها."},{"n":313,"p":66,"c":"الباب الرابع - الميراث › الفصل الرابع - ميراث الزوج والزوجة","t":"إذا طلّق الرجل زوجته في حال المرض وم ات قبل انقضاء الس نة -أي اثني عشر شهراً هلاليّاً -من حين الطلاق ورثت الزوجة عنه سواء أكان الطلاق رجعيّاً أم بائناً عند توفّر ثلاثة شروط: تتزوج المرأة بغيره إلى موته أثناء السنةّ، وإلا لم يثبت الإرث. الأول: أن لا ّ الثاني: أن لا يكون الطلاق بأمرها ورضاها -بعوض أو بدونه ّ - وإلا لم ترثه. الثالث: م وت الزوج في ذلك المرض بس ببه أو بسبب آخر، فل وب رئ من ذلك المرض وم ات بسبب آخر لم ترثه الزوجة ّإلا إذا كان موته في أثناء العدّة الرجعيّة."},{"n":314,"p":67,"c":"الباب الرابع - الميراث › الفصل الرابع - ميراث الزوج والزوجة","t":"ي رث الزوج من جميع ما تركته الزوجة منق ولاً وغيره أرض اً وغيره ا، وت رث الزوجةم ّما تركه الزوج من المنق ولات كالنقود والبض ائع والس يارات ق التحجير والانتف اع والس رقفليّة ونحوها والحيوان ات كمات رث من ح ّ من الحقوق الثابتة له في الأراضي وغيرها، ولا ت رث من الأرض المملوكة له لا عين اً ولا قيمة، وت رثم ّما ثبت فيها من بن اء وأش جار وآلات ص تها من خ ارج التركة ونحو ذلك بالقيمة، فلبقي ة الورثة أني دفعوا لها ح ّ بالنقود ويجب عليها القبول."},{"n":315,"p":67,"c":"الباب الرابع - الميراث › الفصل الرابع - ميراث الزوج والزوجة","t":"يص ّح أن تشترط الزوجة في عقد الزواج بأن تكون وص يةً للزوج في أن تخرج لنفسها من ثلث تركته مقدماً على سائر وصاياه -إن وجدت -من أي أرض سكنية أو غيرها يملكها عند وفاته أو من قيمتها بمقدار نص يبها من ميراثه وهي الثُمن إن كان له ولد والرب ع إن لم يكن له ولد كما تقدم إذا لم يملّكها في حال حياته ما يوازيه أو يزيد عليه في القيمة."},{"n":316,"p":67,"c":"الباب الرابع - الميراث › الفصل الرابع - ميراث الزوج والزوجة","t":"طريق ة التق ويم فيمات رث الزوجة من قيمته هي ما تع ارف عند المق ّومين في تق ويم مثل الدار والبس تان عند البي ع، م ن تق ويم البن اء أو الش جر مثلاً بما هو هو لا بملاحظته ثابت اً في الأرض بدون أجرة ولا بملاحظته منقوض اً أو مقطوعاً، فيعطى إرث الزوجة من قيمته المستنبطة على هذا الأساس. تستحق الزوجة من عين ثم رة النخ لوالش جر وال زرع الموج ودة ح الموت"},{"n":317,"p":67,"c":"الباب الرابع - الميراث › الفصل الرابع - ميراث الزوج والزوجة","t":"ّ الزوج، وليس للوارث إجبارها على قبول القيمة."},{"n":318,"p":68,"c":"الباب الرابع - الميراث › الفصل الرابع - ميراث الزوج والزوجة","t":"لو لم يرغ بال وارث في دفع القيمة للزوجة عن الش جرة والبن اء مثلاً فدفع لها الع ين نفسها كانت ش ريكة فيها كسائر الورثة ولا يجوز لها المطالبة بالقيمة."},{"n":319,"p":68,"c":"الباب الرابع - الميراث › الفصل الرابع - ميراث الزوج والزوجة","t":"الم دار في القيمة على قيمةي وم الدفع لاي وم الموت، فل وزادت قيمة البن اء -م ثلاً -عل ى قيمته حين الموتت رث منها، ول ونقصت نقص من نصيبها."},{"n":320,"p":68,"c":"الباب الرابع - الميراث › الفصل الخامس - الميراث بالولاء","t":"الولاء على قسمين: ولاء ضامن الجريرة وولاء الإمامة."},{"n":321,"p":68,"c":"الباب الرابع - الميراث › الفصل الخامس - الميراث بالولاء","t":"يجوز لمن ليس له وارث من النسب أن يتف ق مع من يش اء على أن يض من جريرته -أي جنايته -فيقول له(: عاقدتك على أن تعق لعني -أي ت دفع دية جن ايتي -وترثن ي) فيق ول الآخ ر(: قبل ت).ف إذا مات الأول ورثه الثاني أيض امن الجريرة، وإذا وجد الزوج أو الزوجة مع الثاني كان له نصيبه الأعلى وكان الباقي لضامن الجريرة."},{"n":322,"p":68,"c":"الباب الرابع - الميراث › الفصل الخامس - الميراث بالولاء","t":"إذا مات ضامن الجريرة لم ينتقل الولاء الى ورثته."},{"n":323,"p":68,"c":"الباب الرابع - الميراث › الفصل الخامس - الميراث بالولاء","t":"إذا فقد الوارث النس بي وض امن الجريرة كان الميراث للإمام (ع)، الا إذا كان له زوج فإنه يأخذ النصف بالفرض وير ّد الباقي علي ه، أو كانت له زوجة فيكون لها الربع والباقي للإمام (ع). وما يرثه الإمام (ع) بولاء الإمامة يص رف بإذن المرجع الديني فيت أمين الحوائج الضرورية للمؤمنين."},{"n":324,"p":68,"c":"الباب الرابع - الميراث › الفصل الخامس - الميراث بالولاء","t":"إذا أوصى من لا وارث له الا الام ام (ع) بجمي ع ماله للفق راء والمس اكين وأبناء السبيل لم تنفذ وصيته الا بمقدار الثلث كما لو أوصى به في غير ذلك."},{"n":325,"p":69,"c":"الباب الرابع - الميراث › الفصل السادس - ميراث الحمل والمفقود","t":"الحم ليرث وي ورث إذا انفص لحيّ اً بأن بقيت فيه الحي اة بعد انفص اله وإن مات من ساعته.وإذا خرج نص فه واس ته ّل ص ائحاًث ُ َّم مات فانفص ل يورث. ميّتاً لم يرث ولم ِ ّ"},{"n":326,"p":69,"c":"الباب الرابع - الميراث › الفصل السادس - ميراث الحمل والمفقود","t":"المقص ود بالحم له والبويضة المخص بة التي تكون في رحم الم رأة، وإذات ّم التخصيب في خارج الرحم ولم تزرع فيه بع ُد لم يشملها حكم الحمل."},{"n":327,"p":69,"c":"الباب الرابع - الميراث › الفصل السادس - ميراث الحمل والمفقود","t":"الحم لم ادام حم لاً لا يرث وإن علم حياته في بطن أ ُ ّمه، ولك ن إذا كان غيره مت أ ّخراً عنه في الطبقة أو الدرجة لمي دفع له شيء من التركة إلى أن يتبيّن الحال. ولو كان للميّت وارث آخر في طبقة الحمل ودرجته -كم الوك ان له أولاد أو أبوان -جاز تقسيم التركة على سائر الورثة بعد عزل مقدار نصيب الحمل فيما لو علم حاله -ولو بالاستعانة بالأجهزة العلميّة الحديثة -م ن أنّه واحد أو متع ّدد ذكر أو أُنثى، وإن لم يعلم حاله يع زل له نصيب ذك رين، ف إن سقط ميّت اً يعطى ما عزل له إلى سائر الورثة بنس بة سهامهم، ول وس قط حيّ اً وتبيّن ّ سم الزائد على الورثة كذلك. أن المعزول أزيد من نصيبه قّ سمت بقيّة التركة فولد أكثر"},{"n":328,"p":69,"c":"الباب الرابع - الميراث › الفصل السادس - ميراث الحمل والمفقود","t":"إذا عزل للحم لنص يب اثنين -م ثلاً -وق ّ ولم يف المعزول بحصصهم استرجعت التركة بمقدار نصيب الزائد."},{"n":329,"p":69,"c":"الباب الرابع - الميراث › الفصل السادس - ميراث الحمل والمفقود","t":"إذا كان للوارث الآخر المتّح دم ع الحمل في الطبقة والدرجة فرض لا يتغيّر على تقدير وجود الحمل وعدمه يعطى نصيبه الكام ل، كم ا إذا كانت له زوجة أو أب وان وكان له ولد آخر غير الحمل فإ ّن نص يبهم -وه وال ثمن للزوجة والسدسان للأبوين -لا يتغيّر بوج ود الحمل وعدمه بعد ما كان له ولد آخ ر، وأ ّما إذا كان ينقص فرضه على تقدير وجوده فيعطى أق ّل ما يص يبه على تقدير ولادته حيّاً، كما إذا كانت له زوجة وأبوان ولم يكن له ولد آخر فتعطى الزوجة عزل الثمن ولك ٍ ّل من الأبوين السدس، فإذا مات الحمل قبل انفص اله حيّ اً ُر ّد ما ُ له الى الزوجة والأبوين حسب استحقاقهم من إرث من مات ولا ولد له."},{"n":330,"p":70,"c":"الباب الرابع - الميراث › الفصل السادس - ميراث الحمل والمفقود","t":"أموال الغائب غيبة منقطعة لا يعلم معها حياته ولا موته، حكمها أن ينتظر بها، وم دّة الانتظ ار أربع سنين يفح ص عنه فيها بإذن القاضي، ف إذا جه لخب ره سمت أمواله بين ورثته الذين يرثونه لو مات حين انته اء مدّة الانتظ ار، قّ مورثه إذا مات قبل ذلك ولا يرثه إذا مات بعد ذلك. ويرث هو ّ وإذا مضى على فقده عشر سنوات أو أكثر من دون فحص عنه بإذن القاضي يجوز تقسيم أمواله بين من يرثونه على تقدير موته عند مضي عشر سنوات على فقده وجهالة خبره."},{"n":331,"p":70,"c":"الباب الرابع - الميراث › الفصل السابع - ميراث َمن تقارن موتهم أو أحتمل سبق موت بعضهم على موت بعض","t":"إذا مات اثنان -بينهما نسب أو سبب يوجب الإرث -في وقت واحد بحيث علم ي، تق ارن موتهم الم يرث أحدهما من الآخر، ب ليرث كّلاً منهما وارثه الح ّ بلا فرق في ذلك بين أس باب الموت ولا بين اتّح اد سبب موتهما وتع ددّه، وهكذا الحكم في موت أكثر من اثنين."},{"n":332,"p":70,"c":"الباب الرابع - الميراث › الفصل السابع - ميراث َمن تقارن موتهم أو أحتمل سبق موت بعضهم على موت بعض","t":"إذا مات المتوارث ان واحتم لفي موت كٍ ّل منهما السبق واللح وق والاقت ران أو علم السبق وجهل السابق، ورث كّل منهما الآخر."},{"n":333,"p":70,"c":"الباب الرابع - الميراث › الفصل السابع - ميراث َمن تقارن موتهم أو أحتمل سبق موت بعضهم على موت بعض","t":"طريقة التوري ثمن الطرفين أن يبنى على حياة كّل واحد منهما حين موت الآخر فيورثم ّما كان يملكه حين الموت ولا يورثم ّما ورثه من الآخر. فم ثلاً: إذا غ رق الزوجان واش تبه المتق دّم والمت أ ّخر ولم يكن لهما ولد ورث الزوج النصف من تركة الزوجة وورثت الزوجة ربع ما تركه زوجه ا، في دفع النصف الم وروث للزوج إلى ورثته مع ثلاثة أرباع تركته الباقية بعد إخراج ربع الزوجة، ويدفع الربع الموروث للزوجة مع نصف تركتها الباقي بعد إخراج نصف الزوج إلى ورثتها. ي ي من المال الأصل ّ هذا حكم توارثهما فيما بينهما، وأ ّما حكم إرث غيرهما الح ّ ورث سابقاً فيرثه الثالث لأحدهما أو كليهما فهو أن يبنى على كون موت الم ّ ي على هذا التق دير، فم ثلاً: إذا غرقت الزوجة وبنتها فالزوج يرث الح ّ من زوجته الربع وإن لم يكن للزوجة ولد غير البنت ولا يرث النص ف، وكذا في إرث البنت فيبنى على سبق موتها، وإذا لم يكن لها وارث غير أبيها كان لأ ُ ّمها التي غرقت معها الثلث ولأبيها الثلثان، وهك ذا إذا غ رق الأب وبنته ولم يكن له ولد سواهما فيكون لزوجته الثمن. ي من المال الم وروث لأح دهما أو كليهما وأ ّم احكم إرث غيرهما الح ّ ورث عن موت ص احبه فيرثه وارثه فهو أن يبنى علىت أ ّخر موت الم ّ على هذا التقدير، ولا يلاحظ فيه احتمال تقدّم موته عكس ما سبق في إرث ماله ي، وإذا كان الم وتى ثلاثة فما زاد فيبنى على حياة الآخ رين عند موت الاصل ّ سم عل ی كّل واحد منهم فيرث ان منه كغيرهم امن الأحي اء وما يرثه الميّت يق ّ ي والموروث كما سبق. ورثته الأحياء دون الأموات، وكيفيّة إرث المال الأصل ّ"},{"n":334,"p":71,"c":"الباب الرابع - الميراث › الفصل السابع - ميراث َمن تقارن موتهم أو أحتمل سبق موت بعضهم على موت بعض","t":"يثبت التوارث في مورد احتمال سبق موت أحدهما أو اقت ران موتهما أو علم ورث السبق وجهل السابق بين من لا يتوقّ فت وارثهم ّإلا على سبق موت الم ّ على الوارث، ولا يثبت بين من يتوقّف توارثهم على ذلك وحصول أمر آخر غير معل وم الحصول، كم ا إذا غ رق الأب وول داه فإنّ الول دين لا يتوارث ان ّإلا مع فقد الأب عند موتهما والمفروض عدم العلم به فلا يحكم بتوارثهما."},{"n":335,"p":71,"c":"الباب الخامس - احكام ختامية","t":"يرج ع في كلم المي رد فيه نص في هذه المدونة الى المجل سالعلمي في دي وان الوق فالش يعي لإجابة المح اكم المختصة على اي استفس ار يتعلق بأحكام الاحوال الشخصية وفق المذهب الشيعي الجعفري."},{"n":336,"p":71,"c":"الباب الخامس - احكام ختامية","t":"للمجل سالعلمي اص دارم ذكرة ايض احية له ذه المدونة بالتنس يق مع مجل س القضاء الأعلى."},{"n":337,"p":71,"c":"الباب الخامس - احكام ختامية","t":"لا يعمل باي نص يتعارض واحكام هذه المدونة. وق دت م الف راغم نت دوين فقراته ا بحم د الله وفض له بت اريخ (٢٩من شهر صفر الخير ١٤٤٧ه)"}];